NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'Luke'

CHAPTERS = {
    1: {
        1: 'MURIN me toto ar intingiedier kasoi pan meakan, me kitail kin kamelele,',
        2: 'Duen ir, me kasokasoi ong kit, me saunkakede o papa pan masan sang ni tapi o,',
        3: 'I ap pil lamedar, me mau, i en inting wong komui, Maing Tiopilus, pwe i lelepokki karos sang ni tapi o kokodo.',
        4: 'Pwe komui en asa duen meakan me komui aleer, me pung melel.',
        5: 'Ni muein Erodes nanmarki en Iudäa, samero amen mia, kisan pwin ong Apia, me mar a Sakarias, o a paud amen sang nain Aron seripein oko, me mar a Elisapet.',
        6: 'Ira karos me pung mon Kot, o ira ineneweita ni en Kaun a kusoned o tiak kan karos.',
        7: 'A sota naira seri, pwe Elisapet li dapwan amen, o ira karos likailapalar.',
        8: 'A kadekadeo ni a kapwaiada a dodok en samero mon Kot ni ansau o, me a pwin pwaisaneki,',
        9: 'Duen a kin wiaui ren samero kan, o ansau en isik mairong lao leler, a kotilong ong nan im en kaudok en Kaun o.',
        10: 'A pokon kalaimun mi liki, wiawia kapakap ni klok en isis.',
        11: 'A tounlang en Kaun amen pwara dong i, kotikot ni pali maun en pei saraui en potik.',
        12: 'Sakarias lao masani, ap lusikida o masapwekada.',
        13: 'A tounlang o masani ong i: Sakarias, der masak, pwe om kapakap pwaidar, om paud Elisapet pan naitikeda seri ol amen, a koe pan ki ong mar a Ioanes.',
        14: 'O a pan kare ong uk peren o popol, o me toto pan perenki a ipwidi.',
        15: 'Pwe a pan lapalap ren Kaun o, a sota pan nim wain, pil so eu song en soko; a pan dir en Ngen saraui nan kupur en in a.',
        16: 'A me toto ren nain Israel akan, me a pan kawuki ong Kaun ar Kot.',
        17: 'A pan tiong mo a ni ngen o roson en Elias, pwen kawuki ong seri kan mongiong en sam arail akan o me sopeik kan ong lamalam en me pung kan, pwen kaonopadang Kaun o pwin aramas lelapok eu.',
        18: 'A Sakarias masani ong tounlang o: Da me i en asaki me wet? Pwe i ol laudalar amen, o ai paud pil likailapalar.',
        19: 'A tounlang sapeng masani ong i: Ngai Kapriel, me kin ariri Kot, o me pakadarado, en lokaia ong uk, o wa dong uk rongamau pukat.',
        20: 'Kilang, koe pan lotong la, o sasa lokaia lao lel ran o, me mepukat pan pwaida, pweki om sota kamelele ai kasoi, me pan pwaida ni a ansau.',
        21: 'A pokon o auiaui Sakarias, puriamuiki a pwapwand nan im en kaudok.',
        22: 'A lao pedoi sang, a solar kak masan ong irail. Irail ap dedeki, me a udial manaman eu nan im en kaudok o. A olol ong irail o lotonglar.',
        23: 'Kadekadeo ran akan en a dodok lao nikier, a kotin purelang sap we koieilang im a.',
        24: 'Murin ran pukat a paud Elisapet liseanda o mimieta nan deu a saunipong limau indada:',
        25: 'Iduen Kaun o kotin wiai ong ia ni ran oko, ni a kotin masan dong ia, pwen kotiki sang ia kanamenok pai ren aramas.',
        26: 'Ni kawonu en saunipong tounlang Kapriel pakadarala sang ren Kot ong nan kanim en Kaliläa eu, me ad a Nasaret,',
        27: 'Ren seripein makelekel amen, me kisin nin ong ol amen, me mar a Iosep, kisan kadaudok en Dawid; seripein makelekel o adaneki Maria.',
        28: 'Tounlang o kotilong ong nan deu a masani ong i: Kaselelia Maing, kom meid pai, Kaun o kotikot re omui! Kom meid pai nan pung en li akan!',
        29: 'A lao kilanger i, o rongadar a masan, ap masapwekadar madamadaua: Duen song en ranamau o.',
        30: 'A tounlang masani ong i: Maria, ender masak, pwe komui me konekonelar ren Kot.',
        31: 'A kilang, komui pan liseanda o naitikeda seri ol amen, a komui pan ki ong mar a Iesus.',
        32: 'Nan i me pan lapalap, o a pan maraneki Sapwilim en Kaun lapalap, o Kaun Kot pan kotiki ong i mol en sam a Dawid.',
        33: 'O a pan kakaunda kadaudok en Iakop kokolata, o sapwilim a wei sota pan imwila.',
        34: 'Maria ap masani ong tounlang o: Daduen mepukat pan kak wiaui, aki i sasa ol amen?',
        35: 'Tounlang o kotin sapeng masani ong i: Ngen saraui pan kotin ti po omui o roson en Kaun lapalap pan kipa komui di, i me saraui o, me pan ipwi sang komui, pan maraneki: Sapwilim en Kot.',
        36: 'O masani, ri om Elisapet pil liseandar ni a likailapala, a pan naitikeda seri ol amen, a kawonu en saunipong ansau wet; iei i me dapwan,',
        37: 'Pwe sota meakot, me Kot sota kak ong.',
        38: 'A Maria potoan ong: Masani, ngai lidu en Kaun o; en wiaui ong ia duen omui masan. Tounlang o ap kotila sang re a.',
        39: 'I ran oko Maria madang kotila pon nana o nan kanim en Iuda eu,',
        40: 'Ap pedelong ong nan im en Sakarias o ranamau ong Elisapet.',
        41: 'Kadekadeo Elisapet lao ronger en Maria a ranamau ong i, seri o ap mokideda nan kaped a; a Elisapet ap direkila Ngen saraui,',
        42: 'O ngil laudeda masani: Komui meid pai ren li akan, o meid iasanai ipwin kupur omui!',
        43: 'A iaduen pai wet a ko sang ia, pwe in en ai Kaun koti dong ia?',
        44: 'Masani, ni ai ronger omui ranamau, seri o ap mokideda nan kaped i aki a peren.',
        45: 'O komui meid pai, pweki komui poson! Pwe a pan pwaida, me Kaun o kotin masani ong komui.',
        46: 'Maria ap masani: Lol ai kapinga Kaun o,',
        47: 'O ngen i perenki Kot ai Saunkamaur.',
        48: 'Pwe a kotin kupurala sapwilim a lidu tikitik o. Kilang, sang met o kokolata di karos pan kapai kin ia,',
        49: 'Pwe a kotin wiaer song en manaman ong ia, me lapalap o mar a me saraui.',
        50: 'A kotin kalangan ong di karos kokolata, ong irail me kin lan i.',
        51: 'O a kotin wia kida lim a manaman akan. O a kotin karawan pasang, me kin lemai nan mongiong arail.',
        52: 'A kotin sikin wei saupeidi kan sang mol ar, ap id kasapwilada me tikitik kan.',
        53: 'A kotin kamede kida kapwa me men mangadar akan, ap kotin kadarala kaip me kapwapwa kan.',
        54: 'A kotin upor kin sapwilim a ladu Israel, o kotin tamataman a kalangan,',
        55: 'Duen a kotin masani ong sam atail akan, ong Apraam o kadaudok a kokolata.',
        56: 'A Maria kotikot re a saunipong silu, ap purelang im a.',
        57: 'Ari, ansaun Elisapet leler pwen naitik, a naitikeda seri ol amen.',
        58: 'O men imp a kan o sau i rongadar, me Kaun o kotin kupura i, rap iang i peren kida.',
        59: 'Kadekadeo auel en ran o re pwara dong sirkomsais seri o; ir ari ki ong mar en sam a Sakarias.',
        60: 'A in a sapeng indada: O kaidin, pwe a pan maraneki Ioanes.',
        61: 'Irail ap indang i: Nan sota sau om men me maraneki met.',
        62: 'Irail ap olol ong sam a, duen me a mauki, seri en adaneki.',
        63: 'I ari poeki slet eu, ap intingiedier o masani: A pan adaneki Ioanes. Irail karos ap puriamuiki.',
        64: 'A madang silang i wasok pasang o tenap a sapadokada; i ari masani o kapinga Kot.',
        65: 'A masak kipadi karos, me kaukauson imp ar, o wiawia pukat lolok sili pon nana en Iudäa karos.',
        66: 'A karos me rongadar, kin nekinekid nan mongiong arail, indada: Da me seri men et pan wiala? Pwe lim en Kaun o kotin iang i.',
        67: 'A sam a Sakarias direkila Ngen saraui ap kokopada masani:',
        68: 'Kapinga ong Kaun Kot en Israel, pwe a kotidier ren sapwilim a aramas akan dore ir ala.',
        69: 'O kotin wiadang kitail kamaur patail sang nan kadaudok en sapwilim a ladu Dawid.',
        70: 'Duen a kotin masanier ren sapwilim a saukop saraui kan, sang tapin kaua kokodo,',
        71: 'Me a pan kotin dore kitail la sang ren atail imwintiti o sang nan pa en me kailong kin kitail,',
        72: 'O kotin kalangan ong sam atail akan, o kotin kupureda a inau saraui,',
        73: 'O kaula eu, me a kotin kauki ong sam atail Apraam, en kotiki ong kitail.',
        74: 'Pwe sen dore sang nan pa en atail imwintiti, ap papa i so masak,',
        75: 'Nin tiak lelapok o pung mon silang i ran karos kokolata.',
        76: 'A koe nai seri pan adaneki: Saukop en me lapalap o, pwe koe pan tiong mon silang en Kaun o, pwen kaonopada sapwilim a al akan.',
        77: 'Pwen kawewe ong sapwilim a aramas kamaur, iei lapwa pan dip ar akan;',
        78: 'Pweki en atail Kot a kalangan melel, me marain dakaraki dong kitail sang poa.',
        79: 'Pwen kamaraini toun pali rotorot o mot en mela, o kainen ong nä atail nan al en popol.',
        80: 'A seri o kakairida, o kelail ni ngen e, o a kin mimi nan sap tan, lao a pan sansal ong Israel.',
    },
    2: {
        1: 'A KADEKADEO ni ran oko nanmarki Aukustus masani, toun sap akan pan wadawad pena.',
        2: 'I wadawad kaieu, me wiauier ni muein Kirenius kopina en Sirien.',
        3: 'Amen amen koieilang udan sap we, pwen iang wadawad.',
        4: 'Iosep ari pil kotila sang Nasaret nan Kaliläa, kotilang Iudäa nan kanim Petleem, me udan kanim en Dawid, pwe i kisan kadaudok en Dawid,',
        5: 'Pwen wadawad iangaki Maria, me kisin nin ong i o me lisean.',
        6: 'Kadekadeo ira lao kot wasa o, a ansau ap leler pwen naitik.',
        7: 'I ari naitikeda na meseni men, ap kitimki pena likau en seri kai, o pwilikidi ong nan deun kamanga man, aki im en kairu a koitalar.',
        8: 'Silepan sip kai mi nan sap o sinsila ar pwin sip ni pong.',
        9: 'A kilang, tounlang en Kaun amen pwara dong ir, o lingan en Kaun dakar irail ada, ir ari masapwekadar kaualap.',
        10: 'A tounlang o masani ong irail: Komail der masak, kilang, i wa dong komail rongamau, me pan kaperenda aramas karos.',
        11: 'Pwe Saunkamaur ipwidi ong komail ran wet nan kanim en Dawid iei Kaun Kristus.',
        12: 'A iet kilel ong komail: Komail pan diar seri o a kidikidiki pena likau en seri o wonon nan deun kamanga man.',
        13: 'A madang pwin en tounlang ngederenia mi ren tounlang o, me kapinga Kot masani:',
        14: 'Kapinga ong Kot wasa ileile o sappa en popol; o aramas konekonelar!',
        15: 'Kadekadeo tounlang kan lao kotila sang ir, kotidala nanlang, silepan sip akan ap inda nan pung arail: Kitail pan kola Petleem pwen kilang me wiauier wasa o, me Kaun o kotin kasale ong kitail er.',
        16: 'Irail ari madangedo, ap diaradar Maria i Iosep o seri o, a wonon nan deun kamanga man.',
        17: 'Irail lao kilanger, rap kalok sili me re kasokasoi ong ir duen kisin seri o.',
        18: 'A karos, me rongadar, puriamuiki en silepan sip oko ar kasokasoi ong irail.',
        19: 'A Maria nekinekid masan pukat karos o madamadauaki nan mongiong i.',
        20: 'O silepa ko puredo kalinganada o kapinga Kot duen karos, me irail rongadar o kilanger, duen a loloke dong irail er.',
        21: 'Kadekadeo murin pong walu pong, ran en a sirkomsais, re ki ong mar a Iesus, duen me tounlang kotiki ong mon a kotin ipwidier.',
        22: 'Ran akan en a kamakelekel lao daulier duen kapung en Moses, ira ap wa dong i Ierusalem, pwen mueid ong Kaun o.',
        23: 'Duen a intingidier nan kapung en Kaun o: Meseni ol karos me saraui ong Kaun o.',
        24: 'O pwen kida mairong eu, duen me intingidier nan kapung en Kaun: Turtel muroi riamen de muroi pulepul riamen.',
        25: 'A kilang, aramas amen mi Ierusalem, mar a Simeon, iei aramas o me pung o masak Kot, o auiaui kapol pan Israel, o Ngen saraui kotikot re a.',
        26: 'A Ngen saraui kotin kasale ong i, me a sota pan mela, mon a pan kilang sapwilim en Kaun Kristus.',
        27: 'O Ngen saraui kotiki ong i, en kolang im en kaudok. A sam o in a lao walong ong nan im en kaudok seri o, pwen kapwaiada duen tiak en kapung o,',
        28: 'I ap koledi i kapinga Kot indada:',
        29: 'Maing, re kotin kasamo sapwilim omui ladu popol duen omui masan,',
        30: 'Pwe mas ai udialer omui kamaur,',
        31: 'Me re kotin kauada sansal mon aramas karos.',
        32: 'Pwen marain eu, me kamaraineki men liki kan, o kalinganada sapwilim omui men Israel.',
        33: 'A sam a o in a puriamuiki meakan, me re indinda duen i.',
        34: 'Simeon ari kapai ir ada indang Maria in a: Kom kotin mangi, men et me sapwile dong kapupedi o kamaureda me toto ren men Israel, kilel eu, me re pan kaundenkoma.',
        35: 'Nan kodlas pan dokodi ngen omui, pwe mongiong en me toto en mulekiada.',
        36: 'O li saukop amen mia, mar a Ana, nain Panuel kisan kadaudok en Aser, me likailapalar, me papaud saunpar isu sang ni ansaun a makelekel.',
        37: 'I ari li odi men saunpar waleisok paieu tauer poa, ap sota kin pedoi sang nan im en kaudok, papa Kot kaisesol o kapakap ni ran o ni pong.',
        38: 'I me pil pwarado ni klok ota, kapinga Kaun o kasokasoi duen i ong toun Ierusalem karos, me auiaui saunkamaur.',
        39: 'Irail kanikiela karos duen kapung en Kaun o, re ap purelang Kaliläa nan kanim Nasaret.',
        40: 'A seri o kakairida, o ngenin, o dire kila erpit, o kalangan en Kot kotin ieiang i.',
        41: 'Ni par karos sam a o in a kotilang Ierusalem iang kamadip en pasa.',
        42: 'A lao saunpar eisokriau, irail ap kotilang Ierusalem, duen re kin wia, pwen iang kamadip en pasa.',
        43: 'Ran oko lao daulier, irail purelang sap arail, a seri Iesus kotikot eta Ierusalem, a sam o in a sota mangi.',
        44: 'A ira kiki ong, me a kotin iang kapar o tiong mo’ra. Ira kokola ran eu, ap rapaki i nan pung en sau’ra o ren men imp arail akan.',
        45: 'Ni ara sota diaradar i, ira ap purelang Ierusalem rapaki i.',
        46: 'Kadekadeo murin pong sili pong ira diaradar i nan im en kaudok, kaipokedi nan pung en snunpadak kan, kotin mamangi ir o kaikainoma irail.',
        47: 'A karos me rongadar i puriamuiki a kupurokong o a sapasapeng.',
        48: 'Ira lao diaradar i, ap puriamuiki. In a ap masani ong i: Nai seri, da me kom wiaki ong kit met? Mangi, sam omui o ngai raparapa kin komui sangesang.',
        49: 'A kotin masani ong ira: Menda koma rapa kin ia? Koma sota asa, me I en mimieta nan me Sam ai?',
        50: 'Ira ari sota weweki a masan ong ira.',
        51: 'A ap kotin iang ira kotidilang Nasaret papa ira, a in a nekinekid masan pukat karos nan mongiong i.',
        52: 'Iesus ari kupurokong, kokoda, lalaudela, o masamas ren Kot o aramas akan.',
    },
    3: {
        1: 'PAR eisoklimau murin nanmarki Tiperius a sapwileda ni muein Pontius Pilatus kopina en Iudäa, o Erodes nanmarki en Kaliläa, o ri a ol Pilipus nanmarki en Ituräa o Trakonitis, o Lisanias nanmarki en Apilene,',
        2: 'Ni muein Anas o Kaipas samero lapalap, masan en Kot ap pwara dong Ioanes nain Sakarias nan sap tan.',
        3: 'I ari kotikot sili nan sap karos ni kail en Iordan, padapadak duen paptais en kalula ong lapwada dip akan,',
        4: 'Duen a intingidier nan puk en masan akan en saukop Iesaia, me masani: Ngil eu likelikwir sili nan sap tan: Komail kaonopada al en Kaun o, kaineneda al a!',
        5: 'Wau karos pan audaud o nana o dol karos pan patapatedi, o me pirok, pan inenla, o me ululen, pan patapatela.',
        6: 'Uduk karos pan udial kamaur en Kot.',
        7: 'A ap masani ong aramas akan, me koieila, pwen paptaisla re a: Dakot, wan oter komail; is me padaki ong komail, en piti sang ni kamekam, me kokodo?',
        8: 'Ari komail kapareda wan kalula mau. A komail depa lamelame, me komail pan indang pein komail: Nan Apraam sam atail. Pwe i indai ong komail, me Kot kotin kak ong wiaki ong Apraam na seri kai takai pukat.',
        9: 'Sile o mier ni tapin tuka kan. Ari, tuka karos, me so wa mau, pan palepaledi o lokidokila nan iai.',
        10: 'Pokon o ap idok re a indada: A da me kit en wia?',
        11: 'A kotin sapeng masani ong irail: Meamen, me a sakit riau, i en ki ong, me sota a. O me kan a kisin manga mia, i en wia dueta.',
        12: 'A saunopwei kan pil pwara dong i pwen paptais, irail potoan ong i: Saunpadak, a da me kit en wia?',
        13: 'A masani ong irail: Komail der ale laude sang me kileledier.',
        14: 'Saunpei kan ap pil kalelapok re a indada: A da me kit en wia? A masani ong irail: Komail der kaloke mal meamen, o der wia sapung ong meamen, a komail ale pwain omail o insenemau kila.',
        15: 'Aramas akan lao kiki ong o mongemongeloleki, me Ioanes me Kristus,',
        16: 'Ioanes ap sapeng masani ong irail karos: I paptais kin komail pil, a me laude sang ia kotido muri, me i sowar ong, en lapwada sal en sapwilim a sut, i me pan paptais kin komail Ngen saraui o kisiniai.',
        17: 'Tanir mi nan lim a, a pan kotin koko melel sapwilim a pera, ap nekid pena wan korn nan sapwilim a im en nak, a dip a pan kotin karong kila kisiniai sokun.',
        18: 'O song toto, me a kotin panaui aramas akan o padaki ong pokon o rongamau.',
        19: 'A nanmarki Erodes, me Ioanes kapung pweki Erodias en ri a ol a paud, o pweki sued karos, me Erodes wiadar,',
        20: 'Kalaudela dip a ni a saliedi Ioanes nan imateng.',
        21: 'A kadekadeo aramas karos lao paptaiselar, o Iesus pil paptaiselar o kotin laolaoki, nanlang ap ritida,',
        22: 'O Ngen saraui kotidi dong i ni mom en muroi men, o ngil eu sang nanlang masani: Koe nai Ol kompok, me I kin peren kida.',
        23: 'Iesus impan saunpar sileisok ni a kotin tapiada saunpadak, o re kikiong me i nain Iosep, me nain Eli,',
        24: 'Me nain Matat, me nain Lewi, me nain Melki, me nain Ianes, me nain Iosep,',
        25: 'Me nain Matatia, me nain Amos, me nain Naum, me nain Esli, me nain Nakai,',
        26: 'Me nain Maat, me nain Matatia, me nain Simei, me nain Iosep, me nain Iuda,',
        27: 'Me nain Ioanan, me nain Resa, me nain Serupapel, me nain Salatiel, me nain Neri,',
        28: 'Me nain Melki, me nain Adi, me nain Kosam, me nain Elmodam, me nain Er,',
        29: 'Me nain Ioses, me nain Elieser, me nain Iorim, me nain Matat, me nain Lewi,',
        30: 'Me nain Simeon, me nain Iuda, me nain Sosep, me nain Ionam, me nain Eliakim,',
        31: 'Me nain Melia, me nain Mena, me nain Matatan, me nain Natan. Me nain Dawid,',
        32: 'Me nain Iese, me nain Oped, me nain Poas, me nain Sala, me nain Naasan,',
        33: 'Me nain Aminadap, me nain Aram, me nain Esron, me nain Peres, me nain Iuda,',
        34: 'Me nain Iakop, me nain Isaak, me nain Apraam, me nain Tara, me nain Naor,',
        35: 'Me nain Seruk, me nain Reku, me nain Palek, me nain Eper, me nain Sala,',
        36: 'Me nain Kainan, me nain Arpaksad, me nain Sem, me nain Noa, me nain Lamek,',
        37: 'Me nain Metusala, me nain Enok, me nain Iared, me nain Maalaleel, me nain Kainan,',
        38: 'Me nain Enos, me nain Set, me nain Adam, me sapwilim en Kot.',
    },
    4: {
        1: 'A IESUS, me dir en Ngen saraui, puredo sang Iordan, o Ngen kotin kalualang i nan sap tan.',
        2: 'O wia songesong pan tewil ran pangaul. A sota kotin konot ni ran oko. Ran akan lao imwisokela ap men konot.',
        3: 'Tewil ap indai ong i: Ma komui sapwilim en Kot, en masani ong takai wet, a en wiala prot.',
        4: 'A Iesus kotin sapeng i masani: A intingidier: Kaidin prot eta, me aramas en memaureki, pwe masan en Kot akan.',
        5: 'Tewil ap kaluadalang i pon nana ileile eu o kasala ong i wein sappa karos ni marep taieu.',
        6: 'Tewil indang i: I pan ki ong komui manaman pukat karos o a lingan, pwe a muei ong ia er, a i pan ki ong, me i mauki.',
        7: 'Ari, ma komui pan pongi ia, karos ap pan sapwilim omui la.',
        8: 'Iesus kotin sapeng i masani: A intingidier: Koe en pongi ong Kaun om Kot; i eta, koe en papa.',
        9: 'I ap kalualang i Ierusalem o kauada i pon kongkong en im en kaudok o indai ong i: Ma komui sapwilim en Kot, kasedi pein komui,',
        10: 'Pwe a intingidier: A pan kasilaki sapwilim a tounlang kai komui, pwen apapwali komui.',
        11: 'O wa komui nan lim ar akan, pwe aluwilu omui der dipikelekel ni takai eu.',
        12: 'Iesus kotin sapeng masani ong i: A lolokido, koe ender kasongesong Kaun om Kot!',
        13: 'Tewil lao kanikiela songesong karos, ap muei sang i ansau kis.',
        14: 'Iesus ap kotin pure dong Kaliläa ni roson en Ngen, ap indand sili nan sap karos me mi imp a.',
        15: 'A kotin kaukawewe nan ar sinakoke kan, o karos kapinga i.',
        16: 'A kotin lel Nasaret, wasa a kotin kakairida ia, ap kotilong song nan sinakoke duen a kin wiada ni ran en sapat o kotida, pwen wadok.',
        17: 'Puk en saukop Iesaia ap wisike dong i a lao lim pasang puk o ap diarada wasa o me intingidier:',
        18: 'Ngen en Kaun kotikot re i, i me a keie kin ia da, pwen padaki ong me samama kan rongamau. A kadar ia do, pwen kaloki ong me salidi kan, me ren saladokela, o me maskun akan pan kilang wasa, o me patau kan pan maioda,',
        19: 'O kaloki saunpar mau en Kaun o.',
        20: 'A kotin lim pena puk o ap kupure ong me papa men o kotidi. Mas en karos nan sinakoke kangkakil i.',
        21: 'I ari tapiada masani ong irail: Kisin likau wet pwaidar mo’mail ran wet.',
        22: 'Ir karos ap kadede o puriamuiki masan kompok kan, me pwili sang silang i, ap indada: Kaidin i nain Iosep?',
        23: 'A ap kotin masani ong irail: Nan melel, komail pan indang ia karaseras wet: Saunwini, sauasa pein uk! Pwe se rongadar duen song kapuriamui, me wiauier nan Kapernaum; ari kom pil wiada dueta wasa et nan sap omui.',
        24: 'A kotin masani: Melel I indai ong komail, sota saukop amen me konekon nan sap we.',
        25: 'A melel I indai ong komail, li odi toto mi nan Israel ni muein Elias, ni ansau nanlang matata par silu o saunipong wonu, ni lek lapalap kipadi sap karos;',
        26: 'A sota amen, me Elias pakadar wong, pwe ren li odi men nan Sarepta nan sap Sidon.',
        27: 'O me tuketuk kan me toto nan Israel ni muein saukop Elias, a sota amen re’rail, me kelailadar, pwe Naeman eta men Sirien.',
        28: 'Karos, me mi nan sinakoke ni ar rongadar mepukat, ap makar kida kaualap,',
        29: 'Re udar sikonlar i sang kanim o, o kalualang i pon kailan dol o, wasa ar kanim kakaudar ia, pwen kasedi sang ia,',
        30: 'A i kotin weid nan pung ar, kotila sang irail.',
        31: 'I ari kotilang Kapernaum kanim en Kaliläa, o kotin kawewe ong irail ni ran en sapat akan.',
        32: 'Irail ari puriamuiki a padak, pwe a masan me manaman.',
        33: 'A aramas amen mi nan sinakoke, me ngen en tewil saut amen ti po a, me weriwer laud,',
        34: 'Inda: Ko sang kit, menda re omui kit Iesus en Nasaret! Kom kotido, en kawe kit ala. I asa, me komui nain Kot saraui.',
        35: 'Iesus ap kidaue i masani: Nenenla o ko sang re a. Tewil lao kasedi i nan pung arail, ap koiei sang re a, sota me sued kot a wiai ong i.',
        36: 'Irail karos ap puriamui kila, kasokasoi nan pung arail indada: Dakot masan pot et? Pwe a masan manaman o roson ong ngen saut akan, irail ap kin ko wei sang.',
        37: 'I ari indand sili nin sap karos wasa o.',
        38: 'I ap kotida sang nan sinakoke, ap kotilong ong nan im en Simon. A saulap en Simon me somau karakar. Irail ari poekipoeki i re a.',
        39: 'I ari koti dong i masani ong somau o, ap madang ko sang, i ari madang paurida papa irail.',
        40: 'Katipin lao kirilar, rap wa dong i ar luet akan karos. I ari kotikidang amen amen lim a kan, kakelail ir ada.',
        41: 'O tewil akan pil kowei sang ren me toto, me weriwer indada: Komui sapwilim en Kot. I ari kotin kidau ir ada, o sota mueid ong irail, en lokaia, pwe re asa, me i Kristus.',
        42: 'A lao wasa ran a kotilang wasa rir, a pokon o raparapaki i, re pokon dong i o kolekol i pwen der koti wei sang irail.',
        43: 'A i kotin masani ong ir: I pil pan padaki rongamau en wein Kot nan kanim tei ko, pwe i me I pakadar kidor.',
        44: 'A i kotin padapadak nan sinakoke en Kaliläa kan.',
    },
    5: {
        1: 'A KADEKADEO ni en aramas toto ar tanga dong imp a, pwen rongerong masan en Kot, a kotikot pon kailan le en Kaliläa,',
        2: 'Ap masani kisin sop riapot, me peipei nan le o, a saused akai keredi sanger widen ar uk kai.',
        3: 'I ari kotida pon apot ren sop oko, war en Simon, kotin poeki re a, en kaiieila ekis sang ni sap o. I ari kaipokedi, kawewe ong aramas sang nan sop o.',
        4: 'I lao kaimwisokela a masan, ap masani ong Simon: Seisei kowei wasa lol, ap kaduedi oma uk kan, pwe koma en saikidi.',
        5: 'A Simon sapeng potoan ong i: Maing, se laiter pong lao lel wasa ran, ap sota saik at, ari so ar masan, me i pan kaduekidi uk en.',
        6: 'Irail lao wiadar met, rap oro pena mam toto; ara uk ari ola.',
        7: 'Irail ari olole kis arail oko, me mi nin apot sop, pwe re en kodo sauasa irail. Irail ari kodo, kadirela sop riapot, ira ari pan mauidi.',
        8: 'Simon Petrus lao kilanger mepukat, ap poridi sang Iesus, potoan ong: Maing, re kotiwei sang ia, pwe aramas sued amen ngai.',
        9: 'Pwe a puriamuiki o ir karos, me iang i, pweki saik ar, me re saikidi.',
        10: 'A pil dueta Iakopus o Ioanes nain Sepedäus ol oko, me iang Simon. Iesus ap kotin masani ong Simon: Koe der masak, pwe sang ansau wet kokola koe pan saikidi aramas.',
        11: 'Irail kaikilong ong liman sap ar sop oko, re ap kasela karos, idauendo i.',
        12: 'Kadekadeo ni a kotikot nan eu kanim, kilang, ol amen mia, me dir en tuketuk. A lao kilanger Iesus, ap pupekidi mas a, poeki re a potoan ong: Maing, ma re kotin kupura, re pan kak ong kamakel ia da.',
        13: 'I ari kotin kapawei lim a sair i masani: I men, koe en makelekel. Ari, a tuketuk madang modi sang.',
        14: 'I ari kotin inapwiedi i, en der indang meamen; a kola kasale ong pein uk samero ko, o kida mairong, pweki om makelekeladar, me Moses masanier, pwen kadede ong irail.',
        15: 'A a madang indand sili o pokon kalaimun pokon pena, pwen rong i o kelailada sang ar somau kan.',
        16: 'I ari kotin kelepela nan sap tan, pwen laolao.',
        17: 'Kadekadeo eu ran ni a kotin kaukaweweda, Parisär o saunkawewe kan, me mod imp a, irail pwarado sang kanim en Kaliläa o Iudäa karos o sang Ierusalem; a roson en Kaun o pwili wei sang i, kakelada amen amen.',
        18: 'A kilang, ol akai roado aramas amen me kokon madak, rap raparapaki duen ar pan kak walang lole, pwilikidi mo a.',
        19: 'A ni ar sota kak diar wasa, me re pan kai dong impa pweki pokon o, rap dauda pon im o, kakiridi i nan os iangaki pet, lao nan pung arail mon Iesus.',
        20: 'A lao mangi arail poson, ap kotin masani: Aramas o, dip om akan lapwa sang uk er.',
        21: 'A saunkawewe o Parisär akan ap mongemongeloleki indada: Is men et, me kin lalaue? Is me kak lapwada dip akan, pwe Kot eta?',
        22: 'A Iesus lao mangi ar mongemongelol, ap kotin sapeng masani ong irail: Da me komail kin mongemongeloleki lol omail?',
        23: 'Da me mongai ren inda, dip om akan lapwa sang uk er, de inda, uda, aluwei?',
        24: 'A pwe komail en asa, me Nain aramas manaman ong lapwada dip akan nin sappa, iei me a kotin masanieki ong me kokon madak: I indai ong uk, uda, ale ki om kola deu om!',
        25: 'A madang uda mo’rail, kida a pet, me a wonon poa, koieilang im a kapikapinga Kot.',
        26: 'Ir karos ap puriamui kida o kapikapinga Kot, o dire kila masak indada: Ran wet kitail kilanger me kapwuriamui melel.',
        27: 'Murin mepukat a kotila sang wasa o, ap masani saunopwei amen, ad a Lewi momod nan wasan nopwei, ap masan ong i: Idauen ia do!',
        28: 'I ari kasela a meakaros, uda, idauenla i.',
        29: 'Lewi ari wiada kamadip lapalap ong i nan im a; a saunopwei ape me toto, me iang i ni tepel.',
        30: 'A Parisär o arail saunkawewe kan lipaned ong sapwilim a tounpadak kan indada: Da me komail iangaki saunopwei o me dipan akan manga o nim.',
        31: 'Iesus ap kotin sapeng masani ong irail: Me kelail sota mau ong saunwini, pwe me somau kan.',
        32: 'I kodon ekeker dong kalula me dipan akan a kaidin me pung kan.',
        33: 'Irail ap potoan ong i: Da me tounpadak en Ioanes akan kaisesol pan pak toto o re kapakap toto, o pil dueta en Parisär akan, a sapwilim omui kan kin tungole o nim?',
        34: 'A Iesus kotin masani ong irail: O komail sota kak ki ong toun kapar en kamadip en kapapaud en kaisesol arain ol kamod mi re’rail!',
        35: 'A eu ran ol kamod pan peuka wei sang irail, i ran oko re ap pan kaisesol.',
        36: 'A kotin masani ong irail karaseras eu: Sota me kin deik ong likau kap ni likau maring; a ma ei, a pan ter pasang likau kap; a kisan likau kap pil sota pan paroki ong likau maring.',
        37: 'A sota me kin kodie ong wain kap nan ed maring; a ma ei, wain kap pan ter pasang ed akan, ap wudokila o ed akan pan ola.',
        38: 'A re kin kodie ong wain kap nan ed kap, ira karos ap nekinek mau.',
        39: 'O sota, me kin nim sang wain maring, pan mauki wain kap, pwe a kin inda: Me maring o me mau sang.',
    },
    6: {
        1: 'KADEKADEO ni ran en sapat kariau a kotin weid nan mat en korn o sapwilim a tounpadak kan ap dolung wan korn o irriris nan pa arail, ap kangkang.',
        2: 'A Parisär akai indang irail: Menda komail kin wiada, me sota pung, en wiaui ni ran en sapat?',
        3: 'Iesus ari kotin sapeng masani ong irail: Komail sota wadoker, me Dawid wiadar ni a men mangadar, i o me iang i?',
        4: 'Duen a pedelong ong nan tanpas en Kot, o ale prot en kasansal, o kangkang o pil ki ong me iang i, me sota pung, aramas en tungole, samero kan eta?',
        5: 'O masani ong irail: Nain aramas pil kaun en sapat.',
        6: 'A kadekadeo ni eu sapat a kotilong ong nan sinakoke kaweweda. A aramas amen mia, me pa a pali maun motorla.',
        7: 'A saunkawewe o Parisär akan masamasan i, ma a pan kakelada i ni ran en sapat, pwe re en kadipa i.',
        8: 'A kotin angi ar lamelam ap masani ong aramas o, me pa a motorla: Uda kodo met! A ap uda ko ong wasa o.',
        9: 'Iesus ap kotin masani ong irail: I men idok re omail, da me pung en wiada ni ran en sapat ren me mau de me sued? En kolekol de kawela maur en aramas?',
        10: 'I ari kotin aupwil sili po’rail masani ong i: Kapawei pa om! A ap wiada, pa a ap kelailada, a maula dueta me teio.',
        11: 'Irail ap makaradar kaualap o kapukapung pena, da me re pan wiai ong Iesus.',
        12: 'Kadekadeo ni ran oko, a kotidala pon nana pwen laolao. I ari kotin laolao ong Kot lao wasa ran.',
        13: 'A lao ran pasang, ap kotin molipei pena sapwilim a tounpadak kan. A kotin piladar ekriamen, me a kamareki wanporon.',
        14: 'Simon me a kotin kaadaneki Petrus, o ri a Andreas, o Iakopus, o Ioanes, o Pilipus, o Partolomäus,',
        15: 'O Matäus, o Tomas, o Iakopus nain Alpäus, o Simon, me adaneki Selotes,',
        16: 'O Iudas nain Iakopus, o Iudas Iskariot, me pangala i.',
        17: 'A lao kotin iang ir kotidi dong wasa kis nan sap patapat o, sapwilim a tounpadak kan toto o aramas ngederenia pokon dong i sang nan Iudäa, o Ierusalem, o Tirus, o Sidon, re mi pon oror, pwen rong i o kakelailada sang ar somau kan;',
        18: 'O me kalokolok ren ngen saut akan ap kelailadar.',
        19: 'A aramas karos men doke i, pwe roson kin pwiliwei sang i, kakel irail karos.',
        20: 'A ap kotin aupwil sili pon sapwilim a tounpadak kan masani: Meid pai komail, me samama, pwe noumail wein nanlang.',
        21: 'Meid pai komail, me men mangadar ansau wet, pwe komail pan medila. Meid pai komail, me kin sangesang ansau wet, pwe komail pan kaurur.',
        22: 'Komail meid pai, ma aramas akan kailong kin komail, o kase komail la, o kidaue komail, o kawela ad omail, pwe dene me sued, pweki Nain aramas.',
        23: 'Komail en peren ni ran o, o lusilus, pwe kilang, pwain omail me lapalap nanlang, pwe iduen me sam arail akan wiai ong saukop akan.',
        24: 'A me suedi ong komail kapwapwa kan, pwe komail anekier omail peren.',
        25: 'Suedi ong komail, me medier, pwe komail pan dupokala. Suedi ong komail, me kin peren ansau wet, pwe komail pan mauk o sangesang.',
        26: 'Suedi ong komail, ma aramas akan karos pan lokaia mau kin komail; pwe iduen me sam arail akan wiai ong saukop likam akan.',
        27: 'A I indai ong komail, me kin rongerong, pok ong omail imwintiti, wiawia mau ong me kin kailong kin komail,',
        28: 'Kapaiada, me kin karia komail la, kapakapa kin ir, me kainsensuede kin komail;',
        29: 'O me pikir uk ni apali en likin sap om, pil ki ong i pali teio, o me pan ki sang om likau pup, pil mueid ong i noum sakit.',
        30: 'Ki ong karos, me kin poeki re om, o me pan atia sang om kapwa, koe der poeki re a, a kapuredo.',
        31: 'A duen me komail men, aramas en wiai ong komail, iduen me komail en wiai ong irail.',
        32: 'Pwe ma komail pok ong, me kin pokepoke komail, da me pan kating pamail? Pwe me dipan akan pil kin pok ong kompoke parail.',
        33: 'A ma komail wiawia mau ong, me wia mau ong komail, da me pan kating pamail? Pwe me dipan akan kin wia pil dueta.',
        34: 'A ma komail pan ki ong irail, me komail akpwainongki, da me pan kating pamail? Pwe me dipan akan pil kin wiai ong me dipan, pwen ale me dueta.',
        35: 'A pok ong omail imwintiti, o wiawia mau, o ki ong so akapwainok, a pwain omail pan lapalap, o komail pan seri en me lapalap o. Pwe a kupura, me so danke o me sued akan.',
        36: 'Komail ari kadek rasong Sam omail me kalangan.',
        37: 'Ender kadeikada a komail sota pan pakadeikada. Ender kariala, a komail sota pan kariala. Lapwada, a komail pan lapwada.',
        38: 'Kisakisa wei, a a pan depuk ong komail dal mau eu, me idang pena, o itik pena, o dir kaualap, me pan ko ong komail. Pwe men song ota, me komail kin songki, iduen a pil pan song ong komail.',
        39: 'A kotin pil masani ong irail karaseras eu: Da, me maskun pan kak kare me maskun? Ira karos sota pan pupedi nan por o?',
        40: 'Tounpadak sota kin laude sang a saunpadak. Ma tounpadak paroki ong a saunpadak, nan a unsokala.',
        41: 'A menda koe kilekilang pul ni mas en ri om ol, ap sota kan ataut o ni pein mas om?',
        42: 'De iaduen, koe pan indang ri om: Ri ai, aui mas, i pan ki sang pul ni mas om, ap sota kilang ataut o ni mas om? Malaun amen koe, ki sang mas ataut o ni mas om, a koe ap pan kak kilang, duen om pan kak kisang pul, me mi ni mas en ri om.',
        43: 'Pwe tuka mau sota pan wa sued. Pil sota tuka sued pan wa mau.',
        44: 'Tuka karos kin diarok kida a wa. Pwe aramas sota kak dolung sang pik ni tuka kamadak, aramas pil sota kin dolung sang wan wain ni tuka mal.',
        45: 'Aramas mau amen kin kapwareda me mau sang nan a pai mau en mongiong i, a me sued amen kin kapwareda me sued sang nan a sued, pwe aua kin kida sang nan audepan mongiong o.',
        46: 'A iaduen, komail kin indang ia: Maing, Maing, ap sota kin wiada, me I kin inda?',
        47: 'Meamen ko dong ia o rongerong ai masan kan, o kapwaiada, nan I pan kasale ong komail, me a rasong.',
        48: 'Nan i me rasong aramas amen, me kauada im eu o weirada lol, o pasonedi pon paip. A lapake lao pwilido, ad ap maimai ong im o, ap so kak kamokidedala, pwe a kakau pon paip o.',
        49: 'A meamen rongerong, ap sota kapwaiada, nan a rasong aramas amen, me kauada im eu nan pwel so pasonedi. A lapake pwil maiai ong, a ap madang rongk pasang, o ola en im o me laud.',
    },
    7: {
        1: 'A LAO kotin erela a masan akan karos ong pokon o, a ap kotilang Kapernaum.',
        2: 'Ladun senturion amen mia, me kasampwal re a, me somau, a pan mela.',
        3: 'A lao rongada duen Iesus, ap poronelang i saumas en Sus akan, poeki re a, en kotido kakelailada a ladu.',
        4: 'Irail lao pwara dong Iesus, ap ngidingideki i potoan ong: A war ong, ren kotin wiai ong i mepukat.',
        5: 'Pwe a kin pok ong toun sap atail o kauadang kit sinakoke o.',
        6: 'Iesus ap kotin iang ir ala. A ni solar non doo sang im o, senturion ap poronelang i kompok kai, potoan ong: Maing re der kangere ir kotido, pwe i sowar, ren ketlong ong nan im ai.',
        7: 'Ngai ari sota kin aka, me i war ong poto dong ir. A re kotin masaniata; a ai ladu pan kelailada.',
        8: 'Pwe ngai pil aramas amen, me mi pan manaman akan, ap kaunda saunpei kai. A ma i pan, indang amen: Kowei! A pan kola; o ong amen: Kodo! A pan kodo; o ong ai ladu: Wiada met! A pan wiada.',
        9: 'Iesus lao mangi mepukat, ap kotin puriamui kila, saupei dong pokon o, me idauendo i, masani: I indai ong komail, me I saik diar poson lapalap duen met, sota ren men Israel.',
        10: 'A me pakadarala kan lao purelong ong nan im o, re ap diarada, me ladu o kelailada.',
        11: 'Kadekadeo murin mepukat a kotilang kanim eu ad a Nain; sapwilim a tounpadak kan toto iang i; o aramas pil me toto.',
        12: 'A lao koren iong wanim en kanim o, kilang, melar amen, me re wawei, ieros en in a, a iei li odi amen; a toun kanim me toto iang i.',
        13: 'Kaun o lao masani i, ap kotin kupurela, masani ong i: Eder sangesang.',
        14: 'I ari koti ong, doke kopa o, a me roa kan ap udi. I ap kotin masani: Manakap, I indai ong uk, paurida!',
        15: 'A me melar o ap modada, pikekidi lokaia. Iesus ap kotiki ong i ren in a,',
        16: 'Masak ap kipa ir edi, o kapikapinga Kot indada: Nan saukop lapalap amen, me pwarado re atail, o Kot me kotier ren sapwilim a aramas akan.',
        17: 'A kasoi pot et duen i lolok sili nan Iudäa o sap karos, me mi imp a.',
        18: 'En Ioanes a tounpadak kan kaire kin i mepukat karos.',
        19: 'Ioanes ap molipeido sapwilim a tounpadak kan riamen, porone ira lang Iesus, masanlang i: Ir me pan kotido, de sen auiaui amen?',
        20: 'Ol oko lao poto dong i, ap potoan ong: Ioanes saunpaptais kadar kit dong ir potoan kalelapok: Ir me pan kotido, de sen auiaui amen?',
        21: 'A ni auer ota a kotin kakelada me toto sang ar somau, o luet, o ngen sued akan, o kotin kapad pasang mas en me maskun toto.',
        22: 'Iesus ap kotin sapeng masani ong irail: Koma u kowei, kaireki Ioanes, meakan komail kilanger o ronger: Me maskun akan kilangada wasa, o me luet akan kin alialu, o me tuketuk kan makelekeleda, o me salongepon kin rong wasa, o me melar akan kin maureda, o rongamau me lolok ong me samama kan.',
        23: 'O meid pai, me sota pan makar kin ia!',
        24: 'A men kadar en Ioanes lao purela, Iesus ap kotin tapiada masani ong pokon o duen Ioanes: Da me komail koieila en kilang nan sap tan? Komail men kilang alek pot, me kin dueduälokki ang?',
        25: 'De da me komail koieila en kilang? Komail men kilang aramas amen, me likau kida likau muterok? Kilang, me kin likau kida likau lingan, o kaped en manga, kin mi nan im en nanmarki kan.',
        26: 'De da me komail koieila en kilang? Saukop amen? Ei, I indai ong komail, a laude sang saukop amen.',
        27: 'Pwe iei i me intingidier due: Kilang, I kadarala mo mui nai men kadar amen, me pan koki al mo’mui.',
        28: 'Pwe I indai ong komail, sota saukop amen me ipwi sang ren li akan, me laude sang Ioanes saunpaptais, ari so, me tikitik nan wein Kot, iei me laude sang i.',
        29: 'A aramas karos, me rongerong i, o saunopwei kan kapinga Kot ni ar iang paptaiseki paptais en Ioanes.',
        30: 'A Parisär o saunkawewe kan sapai ong pein irail ni ar mamaleki kupur en Kot, ap sota iang paptais re a.',
        31: 'A da me I en karasai ong aramas en di wet? O da me irail rasong?',
        32: 'Irail me rasong seri kai, me kin momod nan wasan net akan o likelikwir nan pung arail indinda: Kit kasakasang, a komail sota kakalek; kit kamamauke kin komail, a komail sota sangesang.',
        33: 'Pwe Ioanes saunpaptais pwarado, ap sota kang prot, o sota nim wain, a komail kin inda: Nan tewil kin di poa.',
        34: 'Nain aramas pwarado, manga o nim, a komail kin inda: Kilang, me kaped en manga o kamom sakau, kompoke pan saunopwei o me dipan akan!',
        35: 'A lolekong kin diarok kida na seri kan karos.',
        36: 'A Parisär amen poeki i, en konot re a. I ari kotilong ong nan im en Parisär o kaipokedi ni tepel.',
        37: 'A kilang, li amen mi nan kanim o, me dipan amen, a lao asa, me Iesus kotikot konot nan im en Parisär o, ap wado kokon en alapasta,',
        38: 'O poridi mur i ni aluwilu a sangesang o pikekidi widenki pil en mas a aluwilu a, o limwieki a pwilipeipei, o metik aluwilu a kan o keieki alapasta.',
        39: 'A Parisär o, me lukedo i lao kilanger, ap mongemongeloleki indada: Ma ol men et saukop amen, a pan asa, is li o, me sair i, pwe me dipan amen.',
        40: 'Iesus ap kotin sapeng masani ong i: Simon, I men indai ong uk meakot. I ari indada: Saunpadak, masania do!',
        41: 'Ol amen mia, me aramas riamen pwaipwand ong. Amen ira pwaipwandeki denar limepuki, a amen limeisok,',
        42: 'A ni ara sota men kapungala, a kisakisa kin ira la karos. Indang ia, is re’ra, me pan pok ong i laud?',
        43: 'Simon sapeng potoan ong: I lamelame i, me a kisakis laud ong. A kotin masani ong i: Koe meid pung kasauiada.',
        44: 'I ari saupei dong li o masani ong Simon: Koe kilang li men et, I pedelong ong nan im om, a koe sota ki ong ia pil men widen nä i kat, a i me widenki pil en mas a nä i kat, o limwieki a pwilipeipei.',
        45: 'Koe sota metik ia, a i sota tukedi sang metik nä i kat, sang ni a pedelong lao lel met.',
        46: 'Koe sota usore kin ia le, a met keiekier nä i kat alapasta.',
        47: 'Nan i me I indaki ong uk: Dip a kan me toto me lapwadar, pwe a kin limpok laud; a me dip a sota non lapwada, nan a kin limpok tikitik.',
        48: 'I ari masani ong li o: Dip om akan me lapwadar.',
        49: 'A me iang mod ni tepel o ap tapiada inda nang pung ar: Is men et, me pil kin lapwada dip akan?',
        50: 'I ap kotin masani ong li o: Om poson me dore uk ala, kowei popol!',
    },
    8: {
        1: 'KADEKADEO murin mepukat a kotin kakan sili nan kanim laud o me tikitik kan, padapadak o kaloki rongamau en wein Kot, o ekriamen iang i.',
        2: 'O pil li akai, me a kotin kakelailada sang ngen sued o somau kan, iet akan: Maria, me pil adaneki men Makdala, me tewil isimen koiei sang.',
        3: 'O Ioana iei likond en Kusas en Erodes a saunkoa men, o Susana, o me toto, me papaki i ar kapwa kan.',
        4: 'A aramas totoia lao pokon dong i sang nan kanim akan, karos, ap kotin karaseras masani:',
        5: 'Saunkamor kolan kamor a war akan. Ni a kamokamorok akai ap moredi ong pon kailan al ap tiatidi o manpir en pan lang nam ir ala.',
        6: 'A akai moredi ong pon paip. A lao wosada, a mongedi, pweki a sota lamelamur.',
        7: 'Akai moredi nan tuka teketek, a tuka teketek wosada, kasokä ir ala.',
        8: 'A akai moredi nan pwel mau, ap wosada o wada pan me epuki. Ni a kotin masanier mepukat, ap masan laudeda: Me salong a mia, men rong, i en rong!',
        9: 'A sapwilim a tounpadak kan ap kalelapok re a: Ia wewe en karaseras wet?',
        10: 'I ari kotin masani: A muei ong komail er, en asa me rir en wein Kot, a met akan en asa ni karaseras akan pwe ren kilang, ap sota kilang, o rong, ap sota weweki.',
        11: 'A iet wewe en karaseras o: Masan en Kot iei war akan.',
        12: 'A me mi pon kailan al o, iei ir, me rongadar, a muri tewil pwarada katia sang masan en Kot nan mongiong arail, pwe ren der poson, rap maurela.',
        13: 'A me mi pon paip, iei ir, me kin rong masan o ap pereperen ale, a sota kalau re’rail. Ansau kis re kin poson, a ni ansaun songesong, irail kin pupe sang.',
        14: 'A me moredi nan tuka teketek, iei irail me kin rong, ap koieila tiropeki anan o pai, o inong sued en maur et, rap sokekila, ap sota wa.',
        15: 'A nan sap mau, iei irail, me kin rong masan o, ap nekinek nan mongiong ar inen o mau, o wada nin tiak en kanongama.',
        16: 'Sota me kin isikeda lamp, ap pwainekidi kopa eu, de ki ong pan men wendi a pon deu a, pwe me pan pedelong ong en kilang marain o.',
        17: 'Pwe sota me rir kot, me so pan sansaleta, pil sota me okiok kot, me so pan kalok sili.',
        18: 'Komail ari kalaka duen omail kin rongerong, pwe me a mia, ekis pan ko ong; a me sota a mia, i, me a kiki ong, me a, pan katia sang.',
        19: 'In a o ri a kan ap ko dong i, a re sota kak kaiong impa pweki pokon o.',
        20: 'A ap loki ong i: In ar o ri ar akan poto liki, re men udial ir.',
        21: 'A kotin sapeng masani ong irail: In ai o ri ai mepukat, me kin rongerong masan en Kot o apapwali.',
        22: 'Kadekadeo ni eu ran a kotilang pon apot sop, a sapwilim a tounpadak kan iang i. A kotin masani ong irail: Kitail en kotela le en: Irail ari tangetang koieila.',
        23: 'O ni ar tangetang kokowei, a kotin saimokela; melimel ap koda nan sed. A sop o pwilipwil, a pan mauidi.',
        24: 'Irail ap kai dong i, kaopada i, potoan ong: Maing, Maing, kit pan mela! I ari kipada masani ong ang o iluk en sed akan, rap tikitikala o molelar.',
        25: 'I ap kotin masani ong irail: Ia omail poson? A irail masakada inda nan pung ar: Daduen, is men et, pwe a kin masani ong ang o sed, ir ari duki ong.',
        26: 'Irail ap lele dong sap en Kadara, me sal ong Kaliläa.',
        27: 'I lao kotidi sang, ol amen tu ong i, me kodo sang kanim o, me tanwar en tewil sang mas kokodo, o me kiliso, o a sota kin kauson nan im, pwe a kin mimi nan sousou kan.',
        28: 'I lao kilang Iesus, ap werida, poridi sang mo a indaki ngil laud: Menda re omui ngai, Iesus Sapwilim en Kot lapalap? I men poeki re omui, kom der kalok ia la!',
        29: 'Pwe a kotin masani ong ngen saut o, en koiei sang ren aramas o, pwe pan pak toto a saikidi i; i ari kin sali kidi sal mata o sal en nä kai. A i kamueit ir pasang, o tewil paki i lang sap tan.',
        30: 'Iesus kotin kainoma re a masani: Ia ad om? A potoan ong: Lekion; pwe tewil toto mi re a.',
        31: 'Ir ari poeki re a, ender masani ong irail, me ren kodilang pweleko.',
        32: 'Ari, pwin pwik kalaimun mi wasa o mangamanga sili nin nana o. Irail ari poeki i, en kotin mueid ong irail re en til ong irail. I ari kotin mueid ong irail.',
        33: 'Tewil oko ap kodi sang ren aramas o, ap tilong nan pwin pwik o. Pwin pwik o ap tangedi wei ni aul ong nan sed ap mopila.',
        34: 'Silepa ko lao kilanger me wiauier, rap tangdaui, kolang kanim laud o tikitik kan, kaireki sili.',
        35: 'Irail ap koieila, kilang me wiauier, re ap kola ren Iesus, diarada aramas o, me tewil oko keredi sang lole, momod ni aluwilu en Iesus, likauda o lolekonglar; irail karos masakadar.',
        36: 'Me iang udialer, ap kaire kin irail duen tanwar en tewil a kakeladar.',
        37: 'Men Kadara karos ap poekipoeki i, en koti wei sang re’rail, pwe re masakadar kaualap. I ari kotida pon sop o, ap kotin purelar.',
        38: 'A ol o, me tewil oko kodi sanger, poeki re a, en iang i; a Iesus sota kotin mueid ong i masani:',
        39: 'Purelang deu om, kalok sili duen manaman lapalap, me Kot wiai ong uk er! I ari kola, kalok sili nan kanim o duen manaman lapalap, me Iesus kotin wiai ong i.',
        40: 'Kadekadeo Iesus lao kotin puredo, aramas akan ap kasamo i, pwe irail karos auiaui i.',
        41: 'A kilang, ol amen, ad a Iairus, saumas en sinakoke, kotido poridi ni aluwilu en Iesus o poeki i, en kotilong ong nan im a.',
        42: 'Pwe na ieros seripein amen, me a par ngaulriau, me koren iong mela. A ni a kotikot kokodo, pokon o koi dong i.',
        43: 'A li amen, me nta pwilipwil par ngaulriau, me pwaineki ong saunwini kan a dipisou karos. A sota me kak kakelailada i.',
        44: 'I me apedo mur i, doke ni kailan sapwilim a likau. A pwilipwil en nta madang madada.',
        45: 'Iesus ap kotin masani: Is i me sair ia? A karos lao inda me sota, Petrus o me iang i ap potoan ong: Maing, pokon o kin kapil pena o koi dong ir, a iaduen, re kotin masani: Is i me sair ia?',
        46: 'A Iesus kotin masani: Nan meamen sair ia, pwe I pam, me kel eu ko sang ia er.',
        47: 'A li o lao asaer, me a so kak rirala, ap masapwekada, apedi poridi sang mo a, ap katitiki mon aramas karos, karepan a sair i, o duen a kelailada madang.',
        48: 'A ap kotin masani ong i: Seripein popoleta, om poson me kakel uk ada, kowei popol.',
        49: 'A ni a kotin masaniata, amen potodo sang ren saumas en sinakoke o katitiki ong i: Sapwilim omui seripein melar. Menda kom kangirieki saunpadak o.',
        50: 'A Iesus lao mangi mepukat, ap kotin sapeng i masani: Koe der masak, koe poson ta, a ap pan maureda.',
        51: 'A lao kotilong ong nan im o, a sota kotin mueid ong amen en iang pedelong ong nan pera, Petrus, o Ioanes, o Iakupus eta, o sam en seripein o in a.',
        52: 'A irail karos sangesang o mamaukeki i. A i kotin masani: Komail der sangesang! Pwe a sota melar, a mamair eta.',
        53: 'Rap kaururki, pwe re asa, me a melar.',
        54: 'I ari kotikiiei sang ir nan pera o, a ap kotin ale pa a warong ong i masani: Seripein, paurida!',
        55: 'Ngen en seripein ap pure dong i, i ari madang uda. I ap kotin masani, kisin manga en ko ong.',
        56: 'A sam a in a puriamui kila. I ari kotin inapwiedi irail ren der indang meamen me wiauier.',
    },
    9: {
        1: 'A LAO kotin molipe pena ekriamen oko, ap kotiki ong irail kel o manaman, en kaloedi tewil akan karos o kakelada me somau kan.',
        2: 'I ari kotin porone ir ala, pwen padapadak duen wein Kot o kakelada me somau kan.',
        3: 'O a kotin masani ong irail: Komail der wala meakot pon al o: Sota sokon, de ed, de prot, de moni, amen pil so pan wa sakit riau.',
        4: 'O wasa kis me komail pan pedelong ong nan im eu, komail pan mimieta wasa o, komail lao kowei sang ia.',
        5: 'O meamen kang kasamo komail, komail sapalewei sang kanim o, o sipede sang pwel ni nä omail, pwen kadede ong irail.',
        6: 'Irail ari kokola, kakan sili nan kisin kanim akan, padaki rongamau o kakelada me somau kan wasa karos.',
        7: 'A nanmarki Erodes lao mangi duen meakan, me wiauiki i, ap pingidar, pweki akai katitiki, me dene Ioanes iasadar sang ren me melar akan.',
        8: 'A akai indada, me dene Elias pwarado, o akai me inda, me dene saukop en kaua men iasadar,',
        9: 'A Erodes masani: Ioanes, i me i lepuke sang mong a, a is men et, me i kin rongerong due? A ap men udial i.',
        10: 'A wanporon akan lao pure doer, ap kaireki i karos, me re wiadar. I ari kotin uk irail ada, kotilang wasa rir, nan kanim eu, me ad a Petsaida.',
        11: 'Toun sap o lao asaer, rap idauenla i, i ari kotin kasamo irail, o kotin padaki ong irail duen wein Kot, o kotin kakelada me mau ong.',
        12: 'A lao pan wasa pongier, ekriamen potodo potoan ong i: Re kotin kadar pasang pokon en, pwen kola nan kisin kanim akan o nan sap, en rapaki wasan pweidi o kan ar kisin manga, pwe kitail kotikot nan sap tan wet,',
        13: 'A a kotin masani ong irail: Komail pan ki ong irail kan ar manga! Re potoan ong: Lopon prot eta limau o mam eta riamen mi re at. De se pan kola netie dong pokon kalaimun wet manga?',
        14: 'Pwe irail me ol impan limekid. A a kotin masani ong sapwilim a tounpadak kan: Komail pwini ir pasang wad limek o limek!',
        15: 'Irail ari wiada o kamod irail edi.',
        16: 'A kotin limada lopon prot limau o mam riamen, masanda nanlang, laolaoki, pilitiki pena, kotiki ong sapwilim a tounpadak kan, pwe ren nene ong pokon o.',
        17: 'Irail sak, o karos medier, ap rikada dodo eisokriau luan kamadip o.',
        18: 'Kadekadeo ni a kotin laolao kelep, sapwilim a tounpadak kan iang i. A kotin kainoma re’rail masani: Is me aramas kin inda me ngai?',
        19: 'Irail sapeng potoan ong: Ioanes saunpaptais, a akai me inda Elias, o pil akai kin inda, me dene saukop en kaua men iasadar.',
        20: 'A kotin masani ong irail: A da me komail kin inda is ngai? Petrus ap sapeng potoan ong: Ir me Kristus sapwilim en Kot.',
        21: 'A i me kotin padik inapwiedi irail, ren der indang meamen mepukat,',
        22: 'Masani: Nain aramas pan kalokolok laud, o lokidokila ren saumas, o samero lapalap, o saunkawewe kan, o a pan kamela, o ni ran kasilu a pan maureda,',
        23: 'Ap kotin masani ong irail karos: Meamen men idauen ia i en tonmeteki pein i o ale a lopu ni ran karos, o idedauen ia do.',
        24: 'Pwe meamen kanakanai ong maur a, pan pupe sang. A meamen kasela maur a pweki ngai, pan diarada.',
        25: 'Pwe da me pan mau ong aramas amen, me aneki pena sappa karos, ap kasela pein i o kasapokela pein i?',
        26: 'Pwe me kin namenok kin ia o ai padak kan, i me Nain aramas pil pan namenokki, a lao kodo ni a lingan, o lingan en Sam a, o na tounlang saraui kan.',
        27: 'A melel I indai ong komail, akai irail, me mi met, sota pan mela, irail lao udial wein Kot.',
        28: 'A kadekadeo murin pong walu pong murin masan pukat i ap ukada Petrus, o Ioanes, o Iakopus kotidala pon nana o pwen laolao.',
        29: 'A ni a kotin laolao mom en silang i ap wukila o sapwilim a likau puetepuetela o lingaling.',
        30: 'A kilang, ol riamen iang i masan pena! Ira me Moses o Elias.',
        31: 'Ira pwarado ni ara lingan o mamasani duen a pan kamatala nan Ierusalem.',
        32: 'A Petrus o me iang i me toutouki mair. Ira lao pirida, re ap udial a lingan o ol riamen kotikot impa.',
        33: 'Kadekadeo ira lao kotiwei sang re a, Petrus ap indang Iesus: Maing, meid mau atail kotikot met. Kit en kauada kisin im silikis: Tanpas ar, o en Moses, o en Elias; a sasa me a kasokasoi.',
        34: 'Ni a kasokasoi mepukat, pali en dapok kadupal irail edi, irail ari masakadar ni ar tilong nan dapok o.',
        35: 'O ngil eu peidido sang nan dapok o masani: Iet nai ol kompok, komail en rong i!',
        36: 'A ngil wet lao wiauier, re ap diaradar Iesus ta. Ir ari nenenlata; o ni ran oko re sota kaireki meamen duen me re kilanger.',
        37: 'A kadekadeo manda en ran o irail lao kotidido sang nana o, pokon kalaimun ap poto dong i,',
        38: 'A kilang, ol amen nan pokon o ngil laudeda potoan ong: Saunpadak, i poeki re ir, re kotin masani dong ai tungol putak o, pwe iei ai ieros.',
        39: 'Re kotin mangi, ngen o lao koledi i, a kin madang weriwer, a kin senseroki sili, a ap kin pudopud o meid apwal ni a kin koiei sang i.',
        40: 'Ngai ari poeki ren sapwilim ar tounpadak kan, ren kause wei sang i, a re sota kak.',
        41: 'A Iesus kotin sapeng masani: O di wet meid soposon o sapung, ia arain ai pan mimi re omail? Ia arain ai pan kokoa komail? Wa dong ia noum putak!',
        42: 'A ni a kokodo, tewil ap kapururada o seroki sili i, a Iesus kotin kidaueda ngen saut o, o kakelada putak o, ap kapure ong i ren sam a.',
        43: 'A irail karos puriamuiki manaman en Kot. A ni ar puriamuiki en Iesus a wiawia kan ap kotin masani ong sapwilim a tounpadak kan:',
        44: 'Masan pukat en kaloledi nan salong omail: Nain aramas pan pangala ni pa en aramas.',
        45: 'A irail sota weweki masan wet, pwe a rir sang irail, i me irail sasaki. Irail ari masak kalelapok re a duen masan pot et.',
        46: 'Irail ap pil lamelame, is me pan lapalap re’rail?',
        47: 'A Iesus lao kotin mangi ar lamelam nan mongiong arail, ap ale seri men, kida impa a,',
        48: 'O masani ong irail: Meamen pan apwali kisin seri men et ni ad ai, nan a kin apwali ia, a meamen pan apwali ia, nan a kin apwali, me kadar ia do; a me tikitik re omail, nan i me pan lapalapala.',
        49: 'Ioanes ap sapeng potoan ong: Maing, se kilanger amen, me kausewei tewil akan ni mar ar. Kit ari inapwiedi, pwe a sota kin iang kit idedauen ir.',
        50: 'A Iesus kotin masani ong i: Eder inapiedi, pwe me so kin palian komail, nan a kin iang komail.',
        51: 'A kadekadeo a lao ansau, me a pan peukadala, a ap kotin saupeilang kotilang inen wong Ierusalem.',
        52: 'A kotin poronela men kadar akan, me pan tiong mo a. Irail ari kokola lele dong kisin kanim en Samaria eu, pwen rapaki wasa, me a pan pweiokidi ia.',
        53: 'A re sota kasamo i aki a kotin saupeila kotilang inen wong Ierusalem.',
        54: 'Sapwilim a tounpadak kan Iakopus o Ioanes lao kilanger mepukat, ap potoan ong: Maing, ma re kotin kupura, se pan poeki, kisiniai en moredi sang nanlang, kang irail la, duen Elias wiadar.',
        55: 'A i kotin saupeido, kapung ong ira masani: Koma sota asa is Ngen, me naina kin koma?',
        56: 'Irail ap daulul wei nan eu kisin kanim.',
        57: 'Kadekadeo ni arail kotikot kokodo amen ap potoan ong i: Maing i pan idedauen ir wasa karos me re pan kotila ia.',
        58: 'Iesus kotin masani ong i: Poks akan por ar mia, o manpir en pan lang pas ar mia, a Nain aramas sota wasa en kaula wei mong a.',
        59: 'A kotin masani ong amen: Idauen ia do! A i indada: Maing, komui kotin mueid ong ia mas, i en purela sarepedi sam ai.',
        60: 'A Iesus kotin masani ong i: Me melar akan en sarepedi ar melar akan, a koe kowei kalok sili wein Kot!',
        61: 'Pil amen potoan: Maing, i pan idedauen ir sili, a re kotin mueid ong ia mas, i en kamurimuri ong toun im ai.',
        62: 'A Iesus kotin masani ong i: Sota me pan koledi men weirada pwel, ap kilang muri, a sota koiok ong wein Kot.',
    },
    10: {
        1: 'MURIN mepukat Kaun o pil kotin piladar isiakan o porone irail wei mo a ni wad riamen, en kakan sili nan kanim laud o tikitik kan, wasa me a pein pan kotilang ia.',
        2: 'A kotin masani ong irail: Rak me kalaimun, a toun dodok me malaulau; poeki ren Kaun en rak, en kadarala toun dodok nan a rak.',
        3: 'Komail kola; kilang, I kadar komail la dueta sippul akan nan pung en kidi en wei akan.',
        4: 'Komail der wewa ed en moni, de ed en sailok, de sut, o der ranamau ong meamen nani al o.',
        5: 'A ma komail pan pedelong ong nan im eu, komail pan inda mas: Popol en mimi nan im wet!',
        6: 'A ma popol amen mi wasa o, omail popol pan mimieta re a, a ma so, omail popol pan pure dong komail.',
        7: 'A komail pan mimieta nan im ota, o manga o nim, me mi re’rail pwe toun dodok me warong pwain a. Komail der pedoi sang nan eu im ap kolong ong nan eu.',
        8: 'A ma komail pan pedelong nan eu kanim, o re pan kasamo komail, i wasa komail pan tungole, me pan wisike dong komail.',
        9: 'O kakelada me somau kan, me mi wasa o, o kaire kin irail: Wein Kot koren dong komail.',
        10: 'A ma komail pan pedelong nan eu kanim, o re sota pan kasamo komail, i wasa komail pan pedoi nani al indada:',
        11: 'Pil pwel par, me ko dong kit nan omail kanim, sipede dong komail; ari so, komail en asa, me wein Kot koren dong komail.',
        12: 'I indai ong komail, nan a pan mangai ong Sodom ni ran o sang kanim o.',
        13: 'Suedi ong uk Korasim! Suedi ong Petsaida! Pwe ma manaman akan, me wiaui ong uk er, wiaui ong Tirus o Sidon, nan melel, re pan kalula nan tuk en likau o nan pas.',
        14: 'A a pan mangai ong Tirus o Sidon ni kadeik o sang komail.',
        15: 'A koe Kapernaum, me paidar nanlang, pan pisikondi ong nan pweleko.',
        16: 'Me rongerong komail, nan a kin rongerong ia; o me mamaleki komail, nan a kin mamaleki ia. O me mamaleki, ia, nan a kin mamaleki, me kadar ia do.',
        17: 'Me isiakan ap puredo, pereperen potoan ong: Maing, pil tewil akan udi ong kit ni mar omui.',
        18: 'A kotin masani ong irail: I kilanger Satan likamata liol a pupedi sang nanlang.',
        19: 'Kilang, I ki ong komail manaman, en tiakedi serpent o skorpion, o en poedi kel en imwintiti karos. O sota meakot pan kasuedi ong komail,',
        20: 'Ari so, komail der peren kida, me ngen akan kin udi ong komail, a komail peren kida me ad omail intingidier nanlang.',
        21: 'Ni auer ota Iesus kotin perenda ni ngen e masani: I kapinga komui, Sam ai, kaun pan lang o sappa, me komui okila mepukat sang me lolekong o koiok kan, ap kasale ong seri pwelel akan! Ei Sam ai, pwe iduen me komui kupukupura.',
        22: 'Meakaros muei ong ia er sang ren Sam ai, o sota me asa sapwilim a Ol, pwe Sam eta. O sota me asa Sam, pwe sapwilim a Ol eta, o me sapwilim a Ol pan kasale ong.',
        23: 'I ap kotin saupei dong tounpadak kan, masani ong irail eta: Meid pai por en mas akan me udial, me komail udialer.',
        24: 'Pwe I indai ong komail, saukop o nanmarki kan toto anane udial, me komail kin ududial, a re sota kilanger; a re men rongada, me komail kin rongerong, ap sota rongadar.',
        25: 'A kilang, saunkawewe men ap uda, kasongesong i potoan ong: Saunpadak, da me i en wiada, pwen sosoki maur soutuk?',
        26: 'A kotin masani ong i: Da me intingidier nan kapung o? Daduen om dondoropwe?',
        27: 'A sapeng indada: Koe en pok ong Kaun om Kot mongiong om unsok, o ngen om unsok, o kel om unsok, o om Iamelam unsok, o men imp om dueta pein koe.',
        28: 'A kotin masani ong i: Koe meid sapeng inen, wiada mepukat, a koe pan maurela.',
        29: 'A ap men ak kapungki pein i indang Iesus: A is men imp ai?',
        30: 'A Iesus kotin sapeng masani: Aramas amen momait sang Ierusalem kodila Ieriko ap lodi ong lolap akai, me ter sang a likau kan, o kame i, rap koieila; i ari pan mela.',
        31: 'A samero amen momaitela nani al ota. A ni a kilang i, ap daulul wei sang.',
        32: 'A leap amen pil dueta. Ni a leler wasa o, kilang i, ap daulul wei sang.',
        33: 'A ol en Samaria amen sailok sili ap pil weid wasa o. Ni a kilanger i ap pokela,',
        34: 'Kola re a, o kidim pena a pwal akan, ap ki ong le o wain lole o kamondi i pon dake pa man o, wala nan im en kairu eu, apapwali i.',
        35: 'Manda a pan samala, ap ki ong kaun en im o denar riau indang i: Apapwali i! A ma mekis pan dauli, i pan kapungala, ni ai pan puredo.',
        36: 'A is ren ir silimen, me koe wiaki men impan ol o, me lodi ong lolap oko?',
        37: 'A sapeng: Me wiadar dodok kadek ong i. Iesus ap kotin masani ong i: Ari, kowei ala sang!',
        38: 'A kadekadeo ni ar kotin sailokela, a kotilong ong nan kisin kanim eu. Li amen mi wasa o, ad a Marta, me kasamo i long ong nan im a.',
        39: 'Ri a li amen mia, me ad a Maria, me momod ni aluwilu en Iesus, rongerong a masan.',
        40: 'A Marta kasopisokki pein i a papa i. I ari potodo potoan ong: Maing, re sota kotin kupuroki ri ai li, me sota kin iang ia dodok? Re kotin padaki ong i, en sauasa ia.',
        41: 'A Iesus kotin sapeng masani ong i: Marta, Marta, koe meid nongki o sopisokki okotme.',
        42: 'A me ta kot me kasampwal. Maria piladar pwais mau, me sota pan katia sang.',
    },
    11: {
        1: 'KADEKADEO ni a kotikot wasa kis pwen laolao, a lao kotin erelar, amen sapwilim a tounpadak kan ap potoan ong i: Maing re kotin padaki ong kit kapakap, dueta Ioanes kin padaki ong a tounpadak kan.',
        2: 'A ap kotin masani ong irail: Komail lao wia kapakap, ap inda: Sam at, mar omui en saraui, wei’mui en pwaida,',
        3: 'Kotikido ran wet at tungol kaukaule.',
        4: 'Lapwa sang kit dip at, dueta kit, me kin lapwada karos, me wia dipi ong kit, eder kaluang kit ren me katikatiamau kan.',
        5: 'I ap kotin masani ong irail: Is re omail, me a kompok amen mia o me pan kola re a ni ailep en pong indang i: Kompoke pai, ki ong ia lopon prot silu,',
        6: 'Pwe kompoke pai men pwarado sang a sailok o, ap sota, me i pan kak ki ong i.',
        7: 'A me mi nan im o pan sapeng inda: Koe der kadiropa ia, pwe wanim ritidier, o nai seri ko iang ia nan wasan mair; i so kak paurida o ki ong uk meakot.',
        8: 'I indai ong komail, ma a sota pan paurida o ki ong i aki kompokepa a, nan a pan paurida o ki ong, me itar ong i aki a ngidingid.',
        9: 'I indai ong komail, poeki, a komail pan tungole; rapaki, a komail pan diarada; letelet, a a pan ritida mo’mail.',
        10: 'Pwe karos me poekipoeki, kin tungole; o me kin rapaki, kin diarada; o me kin letelet, nan a pan ritida mo a.',
        11: 'De is sam amen nan pung omail, ma na putak pan poeki na kisin prot, pan ki ong i takai eu? De ma a poeki mam, pan ki ong i serpent amen?',
        12: 'De ma a pan poeki kitor eu, pan ki ong i skorpion amen?',
        13: 'Ma komail, me song sued, asa duen kisakis mau ong noumail seri kan, nan melel kaualap. Sam omail nanlang pan ki ong Ngen saraui ren me poeki re a.',
        14: 'A ap kotin kause wei tewil amen, me lotong. A kadekadeo tewil lao koiei sanger, me lotong o ap lokelokaia, a aramas puriamuiki.',
        15: 'A akai ir katitiki: Nan Peelsepup, saumas en tewil akan, me a kauseki sang tewil akan.',
        16: 'A akai kasongesong i, poekipoeki kilel eu sang nanlang.',
        17: 'A ap kotin angi ar lamelam, masani ong irail: Wei karos ma a pan u pena nan pung a, a pan ola; o ma toun im eu pan u pena nan pung a, a sota pan pwaida.',
        18: 'A iaduen, ma Satan u ong pein i, a wei pan kak pwaida? Aki komail indinda me dene ngai kause wei tewil akan ki Peelsepup.',
        19: 'Ma I kin kauseki wei Peelsepup tewil akan, a is me noumail ol akan kin kause kin irail? Irail ari pan omail saunkapung.',
        20: 'A ma I kauseki wei lim en Kot tewil akan, nan wein Kot lel ong komail er.',
        21: 'Ma me kelail o, me audeki kapwa en pei, pan sinsila im a, nan a kapwa nekinekid mau.',
        22: 'A ma amen, me kelail sang i, pan palian i o kaloedi i, ap pan atia sang a kapwa en pei, me a kelekier, o nek pasang kapwa en kul.',
        23: 'Meamen, me sota iang ia, iei me palian ia, o me sota kin dolung penang ia, iei me kin kasapoka pasang.',
        24: 'Ngen saut lao kowei sang ren aramas, a kin tangatang sili nan sap tan akan, rapaki wasan kamol, a sota, me a diarada, i ap kin inda: I ap pan purelong ong nan im ai, me i pedoi sanger.',
        25: 'A lao puredo, a diar, me a kokok o kapwater,',
        26: 'I ari koieila, ale ong i ngen isimen, me sued sang pein i. Irail ap pedelong ong lole, rap kakauson ia; a aramas pan sued sang mas.',
        27: 'A kadekadeo ni a kotin mamasani mepukat, li amen, kisan pokon o, ap potoan ong i: Meid pai kupur o, me wia ir adar, o didi kan, me re kotiki!',
        28: 'A i kotin masani: Ei, meid pai, me kin rong masan en Kot ap kapwaiada.',
        29: 'A pokon o lao tengeteng pena, a kotin masani: Di wet meid sued! Re kin rapaki kilel eu, a sota kilel pan sansal ong ir, pwe kilel en Iona eta.',
        30: 'Pwe duen Iona kilel eu ong men Niniwe, iduen Nain aramas ong di wet.',
        31: 'Li nanmarki en pali air amen pan u ong ol akan en di wet ni kadeik o pan kari ir ala, pwe a pwrarado sang ni imwin sappa, pwen rong lolekong en Salomo. A kilang, me laude sang Salomo mi met.',
        32: 'Ol en Niniwe kan pan u ong di wet ni kadeik, o pan kariala i, pwe re kalula ni ar rongadar padak en Iona. A kilang, me laude sang Iona mi met.',
        33: 'Sota me kin isikeda lamp, ap kila wasa rir, pil so pan kopa, a pon deu a, pwe me pan pedelong ong, en kilang marain o.',
        34: 'Por en mas marain en pali war. Ma mas om makelekel, war om karos pan dir en marain. A ma mas om me sued, war om karos me pil dir en rotorot.',
        35: 'En kalaka, pwe marain mi lol om, der rotorot!',
        36: 'Ma war om dir en marain kaualap, o sota kisan rotorot mia, karos pan dir en marain dueta lingan en lamp, me kin sensere uk ada.',
        37: 'A ni a kotin kaparok, Parisär amen luke i, en konot re a. I ari kotilong kotidi nin tepel.',
        38: 'A Parisär lao udial, ap puriamuiki, me a sota kotin omiom mon konot.',
        39: 'A Kaun o kotin masani ong i: Nan komail Parisär akan kin widen likin dal o plet, a lol omail me dir en me re kuliada o me sued.',
        40: 'Nan pweipwei komail, kaidin i me wiadar pali liki, pil wiadar pali lole?',
        41: 'A kisakis weita duen komail kak ong! A kilang, karos pan makelekel ong komail.',
        42: 'Suedi ong komail Parisär akan, pwe komail, kin mairongki eisokkis eu en minse, o raute o song en kisin tan tuka kai, ap sota insenoki kadeik o limpok en Kot! Wiada mepukat ap pil kapwaiada me tei kan.',
        43: 'Suedi ong komail Parisär akan, pwe komail men mondi leppantam nan sinakoke kan o mauki, ren ranamau ong komail nan wasa en netinet akan.',
        44: 'Suedi ong komail, pwe komail rasong sousou kan, me so sansal, o aramas alialu poa, ap sasa ir!',
        45: 'Saunkawewe men ap sapeng potoan ong i: Saunpadak, komui pil kin suede kin kit masan pukat.',
        46: 'A i kotin masani: Pil suedi ong komail saunkawewe! Pwe komail kin katoutou kila kapwa en wisik toutou aramas akan, ap sota sairki sondin pa omail.',
        47: 'Suedi ong komail! Pwe komail kin apapwali sousou en saukop akan, a sam omail akan kame ir ala.',
        48: 'Komail ari kin kadede o peren kida wiawia en sam omail akan. Pwe re kame ir ala, a komail apapwali ar sousou kan.',
        49: 'I me erpit en Kot indada: I pan kadar wong irail saukop o wanporon akan, a akai irail re pan kamela o pwaki irail sili.',
        50: 'Pwe ntan saukop akan, me kapwilipwili weier sang ni tapin kaua kokodo, en kapokon ong di wet.',
        51: 'Sang ntan Apel lel ntan Sakarias, me kamelar nan pung en pei saraui o im en kaudok, ei I indai ong komail, a pan kapokon ong di wet.',
        52: 'Suedi ong komail saunkawewe! Pwe komail atia sang men kapir pan lolekong. Komail sota pan pedelong, ap inapwiedi, me men pedelon ong.',
        53: 'A ni a kotin mamasani ong irail mepukat, saunkawewe o Parisär akan ap tapiada palian i kaualap, kalekalelapok re a song toto,',
        54: 'O re masamasan i, o raparapaki, ma re sota kak diar meakot sang ni a masan akan, pwe ren kadipa i.',
    },
    12: {
        1: 'ARAMAS toto ap pokon pena lao kidalar, irail lao it pena, i ap kotin tapiada masani ong sapwilim a tounpadak kan: Komail kalaka kalep en Parisär akan, me malaun.',
        2: 'Pwe sota me rir kot, me sota pan sansalada. Pil sota me okiok kot, me so pan kalok sili.',
        3: 'Ari, me komail pan indada ni wasa rotorot, i me pan sansal nan marain. O me komail pan monginingin nan pera kan, i me pan kalok sili pon im akan.',
        4: 'A I indai ong komail, kompok pai kan, komail der masak irail, me kin kamela pali war, ap solar kak wia meakot.',
        5: 'A I pan kaasa kin komail, me komail en masak: Masak i, me manaman ong kamela aramas ap kak kasela nan pweleko. Melel I indai ong komail, i me komail en masak.',
        6: 'Siok limen sota kin netila ni denar riau? Ari so, sota amen irail me Kot kin maliela.',
        7: 'Ari, pil pit en mong omail karos me wadawad penaer. Komail ari der masak, pwe komail me mau sang siok toto.',
        8: 'A I indai ong komail, meamen ponasa ia mon aramas, i me Nain aramas pan ponasa ren tounlang en Kot akan.',
        9: 'A meamen kamam kin ia mon aramas, i me pan kamamaki mon tounlang en Kot akan.',
        10: 'O meamen me pan lokaia sued duen Nain aramas, a pan kak lapwada. A me lalaue Ngen saraui, a sota pan lapwada.',
        11: 'A ma re pan wa komail la nan ar sinakoke kan mon kapung o ren me manaman akan, komail depa lamelame, da me komail pan sapengki de me komail en inda.',
        12: 'Pwe Ngen saraui pan kapame kin komail ni klok ota, me komail en inda.',
        13: 'A amen toun pokon potoan ong i: Saunpadak, kom kotin masani ong ri ai ol o, en nek pasang at soso.',
        14: 'A kotin masani ong i: Aramas o, is me kasapwil ia da, en saunkapungla o saunnene re oma?',
        15: 'O kotin masani ong irail: Kalaka norok sued, pwe kaidin kapwa toto, me aramas amen kin memaur kida!',
        16: 'A kotin masani ong irail karaseras eu: Ol kapwapwa amen mia, me sap we kaparapar kaualap.',
        17: 'I ari lamelame indada: Da me i en wiada? Pwe solar wasa en nekinek ia ai kapwa kan.',
        18: 'I ari indada: Nan iet me i pan wiada: I pan palang pasang ai im en nak kan, ap kauada me laude sang kai; i wasa me i pan nekidala me wosadang ia o ai dipisou karos;',
        19: 'A i pan indang ngen i: Ngen i, dipisou toto ong par toto, me nekineki ong uk er. En moleilei, o manga, o nim o perenta!',
        20: 'A Kot ap masani ong i: Pweipwei men koe, pwe pongpong wet ngen om pan ilakido. A is me pan aneki kapwa pukat, me koe nanak penaer?',
        21: 'Nan iduen me kin roporop pena dipisou ong pein i, ap sota kapwapwa ren Kot.',
        22: 'A a kotin masani ong sapwilim a tounpadak kan: I me I indai ong komail, eder lamelame maur omail, me komail pan tungole, pil iermen pali war, me komail pan likauki!',
        23: 'Maur me kasampwal sang manga, o war me mau sang likau.',
        24: 'Kalelapok ong rape kan! Re sota kin kamorok, re pil sota kin nak pena, pil sota arail pera de im en nak, a Kot kin kotin katungole ir. A komail so kasampwal sang manpir kaualap?',
        25: 'A is nan pung omail, ni a ngongki, me pan kak use pasang pein i ki tipong en pa eu?',
        26: 'Ari, ma komail sota kak ong wiada me mangai, a da me komail kin ngongki okotme?',
        27: 'Kalelapok ong kiop akan, me mi nan sap, duen ar kakairida! Re sota kin dodok, o re sota kin monkol pena. A I indai ong komail, pil Salomo ni a lingan karos sota a likau dueta apot irail.',
        28: 'Ari, ma iduen Kot kotin kapwataki dip, me mi nan sap ran wet, a lakap pan lokidokila nan stop, iaduen a sota pan madang kalikauwiada komail, me poson tikitik?',
        29: 'A komail, ender ngongki, me komail pan manga o nim, o komail der insensued!',
        30: 'Pwe mepukat men liki kan kin ngongongki. Pwe Sam omail, me kotikot nanlang, mangi, me mepukat karos mau ong komail.',
        31: 'A rapaki sapwilim a wei, a mepukat pan pousalang komail.',
        32: 'Der masak pwin tikitik koe, pwe iet kupur en Sam omail: En ki ong komail wei o.',
        33: 'Netikila omail kapwa kan, ap kisakisa wei, wiai ong komail ed ko, me sota pan maringala, o pai nanlang, me so pan ola, wasa me lipirap men so kak ong, o man en mot so kak kawela ia.',
        34: 'Pwe wasa omail pai mi ia, iei wasa mongiong omail pil kin mia,',
        35: 'Nan luke pamail en katengteng pena o omail ser en isis',
        36: 'O komail en dueta aramas akan, me auiaui ar monsap ni a pan kodo sang kamadip en papaud, pwe i lao kodo letelet, re en madang ritingada mo a.',
        37: 'Ladu ko meid pai, me monsap o ni a pan pwarado, diar ar masamasan. Melel I indai ong komail, a pan kaiada a likau o kamod irail edi ong manga, ap pan apapwali irail.',
        38: 'O ma a pwarado ni auer kariau, de kasilu, ap diar ir masamasan, nan meid pai ladu pukat.',
        39: 'A komail en asa, ma kaun pan im o asaer ansaun lolap o pan pwarado, a pan masamasan o so pan mueid ong, im a en kulia sang.',
        40: 'Komail ari pil ononop, pwe Nain aramas pan pwarado niansau me komail sasa.',
        41: 'Petrus ap potoan ong i: Maing, re kotin masani dong kit karaseras wet, de ong irail karos?',
        42: 'A Kaun o kotin masani: Ari is saunkoa lelapok o lolekong, me a monsap kasapwilada, en kaunda a ladu kan, pwen nek ong irail kan ar manga ni ansau me kon on?',
        43: 'Meid pai ladu o, me a monsap pan diarada wiawia duen met ni a pan pwarado!',
        44: 'Melel I indai ong komail, a pan kasapwiladang i pon a dipisou karos.',
        45: 'A ma ladu o pan lamelame nan mongiong i: Ai monsap pwapwand, o a pan tapiada kame ladu o lidu kan, o manga o nim, o kamom sakau,',
        46: 'Monsap en ladu o ap pan pwara do ni ran o, me a so auiaui i, o ni auer, me a sasa, o a pan lepuk pasang i, o kasapokalang nan pung en me soposon akan.',
        47: 'A ladu o, me asa kupur en a monsap, a sota kaonopada pein i, pil sota wiada kupur a, nan i me pan kamekam kaualap.',
        48: 'A me sasa, ap wiadar me mau ong kalokolok, nan i me pan kalokolok tikitik. Pwe me aleer me toto, i me pan kida me toto; o me koaki me toto, pan purokido me toto.',
        49: 'I kodon saundi kisiniai sappa, a da me I en wiada, ma a saundier?',
        50: 'A mas I pan paptaise kila paptais eu; I ap patau kila melel, a lao daulier.',
        51: 'Komail lamelame, me I kodon ki ong sappa popol? I indai ong komail: So! A pwen kumuei suedala.',
        52: 'Pwe sang met kokola limen toun im eu pan liak toror pasang; silimen pan palian riamen, o riamen pan palian silimen.',
        53: 'Sam pan palian na putak, a putak o pan palian sam a; in pan palian na seripein, a seripein pan palian in a; a li amen pan palian na ol a paud, o en na ol a paud pan palian li o.',
        54: 'A kotin masani ong pokon o: Komail lao udial dapok sang kapin lang, komail kin inda: A pan katau; o a pan pwaida',
        55: 'O ma komail kin kilang ang a usang ni pali air, komail kin inda: A pan karakar; o a pan wiaui.',
        56: 'Malaun komail! Komail asa kasaui mas en sappa o lang, a da me komail sasaki kasauida ansau wet?',
        57: 'A da me pein komail sota kasauia kida me pung?',
        58: 'A ma koe pan iang me palian uk kolang kapung o, en nantiong pon al o, en kapungala re a, pwe a de pang uk alang saunkapung, a saunkapung pang uk ala ren silepan imateng, a silepan imateng pan kase uk ala nan imateng.',
        59: 'I indai ong uk: Koe sota pan koda sang wasa o, koe lao kapungala lua karos.',
    },
    13: {
        1: 'NI ansau o akai mia, me potoan ong i duen men Kaliläa kai, me Pilatus doleki nt’ arail ar mairong.',
        2: 'A kotin sapeng masani ong irail: Komail kiki ong, me men Kaliläa pukat me dipan akan mon men Kaliläa tei kan, pweki ar kalokolok o?',
        3: 'Ngai, me indai ong komail: So! A ma komail sota pan kalula, komail karos pan mela dueta.',
        4: 'De irail ekwalemen ko, me im en ruk en Siloa pupedi ong poa, kame ir ala, komail kiki ong, me irail me sued sang aramas akan, me kaukauson Ierusalem?',
        5: 'Ngai me indai ong komail: So! A ma komail sota pan kalula, komail karos pan mela dueta.',
        6: 'A kotin karaseras ong irail masani: Aramas amen mia, me a tuka pik apot padedi nan a mat en wain, ap kodon rapaki wa, a sota me a diarada.',
        7: 'A ap indai ong saumat en wain: Kilang, par silu i kodon rapaki wan pik pot et, a sota, me i diarada; paledi, da me a pinaki mal wasa o!',
        8: 'A a sapeng indang i: Maing, pui sang pil par wet, pwe i en weirada ni tapi, o ki ong pwel mau.',
        9: 'A ma a pan wa, ari me mau, a ma so, komui ap pan paledi sang.',
        10: 'A kotin padapadak nan sinakoke eu ni ran en sapat.',
        11: 'A kilang, li amen mia, me ngen en somau ti poa par ngaulwalu, a kos pena o sota man kak uda.',
        12: 'Iesus lao kotin masani i, ap molipei wong i masani ong i: Li, koe en maioda sang om somau!',
        13: 'I ap kotin pwil po a lim a kan, i ari madang kasinenda, kapikapinga Kot.',
        14: 'A saumas en sinakoke o makara kida pan Iesus a kakelada i ni ran en sapat, ap sapeng indang pokon o: Ran wonu, aramas en dodok, i ansau me komail kodon kakelada, a iermen ni ran en sapat!',
        15: 'Kaun o ap kotin sapeng i masani: Malaun koe, kaidin komail karos kin lapwada kau o esel sang deu a kalualang nim pil ni ran en sapat?',
        16: 'A li men et, me nain Apraam seripein, me Satan saliedi par ngaulwalu, me so mau, en lapwada ni ran en sapat?',
        17: 'Ni a kotin masani mepukat, karos me palian i, ap namenokala o aramas karos peren kida wiawia mau kan karos, me wiauier pa a.',
        18: 'A a kotin masani: Wein Kot rasong da? O da me I en karasai ong i?',
        19: 'A rasong wantuka eu, me aramas amen kasela nan matuel ap wosada, wiala tuka kalaimun pot, o manpir en pan lang kaukauson nan ra kan.',
        20: 'A pil kotin masani: Da me I en karasai ong wein Kot?',
        21: 'A rasong kalep kis, me li amen ale, okila nan kasak en plaua silu, karos lao mutala.',
        22: 'Ni a kotilang Ierusalem, a kotin padapadak sili nan kanim laud o tikitik kan.',
        23: 'Amen ap potoan ong i: Maing, me malaulau pan maurela? A kotin masani ong irail:',
        24: 'Ngiangi en pedelong ong nan wanim tätik, pwe I indai ong komail, me toto pan sosong pedelong ong, a sota pan kak.',
        25: 'A kaun pan im o lao udar ritingidier wanim o, komail ap pan pikikidi letelet ni wanim o indada: Maing, ritingida sang kit! A ap pan sapeng indang komail: I sasa komail, o wasa me komail ko sang ia.',
        26: 'Komail ap pan pikikidi indada: Kit me manga o nim imp omui, o komui pil kaukawewe nan atail al akan.',
        27: 'A i me pan inda: I indai ong komail, I sasa komail o wasa komail ko sang ia, ko wei sang ia, komail karos me wiawia sued.',
        28: 'Sangesang o teterok ap pan wiaui, komail lao kilang Apraam, o Isaak, o Iakop, o saukop akan karos nan wein Kot, a komail pisikonla sang.',
        29: 'Nan re pan kodo sang nan mas en lang, o sang nan kapin lang, o sang nan apang, o sang air en lang, o re pan mondi ni tepel nan wein Kot.',
        30: 'A kilang, me pwand akai mia, me pan madang, o me madang kai mia, me pan pwand.',
        31: 'Ni auer ota Parisär akai kodo indai ong i: Koti wei sang met, pwe Erod pan kame komui la.',
        32: 'A kotin masani ong irail: Komail u kowei, indai ong poks ota: Kilang I kin kause wei tewil oko o kamakamaureda ran wet o lakap, a ni kasilu en ran I pan imwisokela.',
        33: 'I en kokola ran wet, pil lakap, pil pali, pwe sota saukop amen me pan kamela likin Ierusalem.',
        34: 'Ierusalem, Ierusalem, me kin kamela saukop akan o kasuk, me pakadara dong uk, pan pak toto I men kapokon pena noum seri kan dueta lituk amen kin kompwal pena na kan pan pa a, a komail kanger,',
        35: 'Kilang, im omail pan tanla, pwe I indai ong komail, komail solar pan kilang ia, lao a pan pwaida omail pan inda: Kapinga ong me kotido ni mar en Kaun!',
    },
    14: {
        1: 'KADEKADEO ni a kotilong ong nan im en kaun pan Parisär amen, pwen konot ni ran en sapat; a irail masamasan i.',
        2: 'A kilang, aramas amen mia wasa o, me lisongepo.',
        3: 'Iesus ap kotin sapeng masani ong saunkawewe o Parisär akan: Me pung, en kakelada ni ran en sapat?',
        4: 'Irail nenenla. I ap kotin sair i, kakelada o kadara wei.',
        5: 'Ap kotin sapeng masani ong irail: Is re omail, me na as de kau pupedi ong nan por o, me so pan madang apiada sang ni ran en sapat?',
        6: 'A irail sota kak sapengki i meakot.',
        7: 'A kotin masani ong toun kapar karaseras eu, ni a kotin mangi, me re inong iong en mondi ni tapin tepel, masani ong irail:',
        8: 'Koe lao pan luke dong kamadip en kapapaud ren meamen, ender mondi ong leppantam, pwe ele amen, me lapa sang koe lukedor.',
        9: 'O me luk uk edo o pil i, pan kodo indai ong uk: Ki ong ol men et deu om! A koe pan namenok kodido ong nan roulap.',
        10: 'A koe lao paluke, kola mondi ong nan roulap, pwe me luke uk lao pwarado, en indai ong uk: Kompoke pai, kotidato! Koe ari pan kaindand nan pung en ir, me iang uk ni tepel.',
        11: 'Pwe karos me kin kasapwilada pein i, pan kasapwilidi, o me kin kasapwilidi pein i, pan kasapwilada.',
        12: 'Ap pil kotin masani ong me lukedo i: Kom lao wiada konot en ni sauas de nin sautik, eder lukedo kompokepa om ko, de ri om akan, de sau om, de men imp om kapwapwa kan, pwe re de pil luke uk, o depuk ong uk.',
        13: 'A ma koe pan wia kamadip, en lukedo me samama o me pali duk kai, o me sikilikil, o me maskun akan.',
        14: 'Koe ari pan meid pai, pwe irail sota pan kak depuk ong uk, a a pan depuk ong uk ni ran o, me pung kan pan maureda.',
        15: 'A amen ir, me iang ni tepel o lao rongadar mepukat, ap potoan ong i: Meid pai, me pan sak prot nan wein Kot.',
        16: 'A a kotin masani ong i: Aramas amen mia, me wiadar kamadip lapalap o luke pena me toto.',
        17: 'O kadarala na ladu o ni dokan kamadip, pwen kaire kin irail, me pan toun kapar: Komail ukedo, pwe meakaros onoper.',
        18: 'Irail ap wiaki eu ikidiki okotme. Men mas indai ong i: I netiada sap eu, i pan kola kilang; i poeki re om, koe en kadar ia la.',
        19: 'A amen inda: I pwainda kau ol ek, a met i pan kola kilang ir; i poeki re om, koe en kadar ia la.',
        20: 'A amen inda: I paudeki li amen, i me i sota kak kokila.',
        21: 'Ladu o ari purodo, kaireki a monsap meakan. Monsap o ap makara kidar indai ong a ladu: Tange wei nani al laud o al tikitik en kanim o wado me samama kan, o me pali duk, o me sikilikil, o me maskun akan.',
        22: 'A ladu o indada: Maing, a wiauier duen omui masan, a deun akai pil mia.',
        23: 'Monsap o ap indai ong a ladu: Kakan sili nani al o ni kailan kel akan, papain ir do, pwe im ai en tounla!',
        24: 'A i indai ong komail, nan sota amen ren ol oko, me paluke, pan song ai kamadip.',
        25: 'A pokon kalaimun idauenla i. I ari saupei ong irail masani:',
        26: 'Meamen kodo re i, ap so maliela sam a, o in a, o a paud, o na seri kan, o ri a ol, o li akan, o pil pein maur a, nan a sota pan kak ai tounpadak.',
        27: 'A meamen so kida a lopu o idauen ia do, a sota pan kak ai tounpadak.',
        28: 'Pwe is re omail, me pan kauada im en taulik eu, me sota pan mondi mas ap lamelame duen pwain a, ma a pan kak ong de so?',
        29: 'Pwe a de pasonedi, ap sota kak kanikiela; a karos, me udial, pan kaurureki i,',
        30: 'Indada: Aramas men et pikikidi kauada im, ap sota kak kanikiela.',
        31: 'De is nanmarki o, me pan mauin ong amen nanmarki, me sota pan mondi mas ap lamelame, ma a pan kak kaloekidi aramas nen aramas rianen?',
        32: 'A ma so, a pan kadarala men kadar akai, poekipoeki muei mau ni ara non doo pasang.',
        33: 'Nan iduen amen amen komail, me so muei sang meakaros, nan a sota pan kak ai tounpadak.',
        34: 'Sol me mau, a ma sol sarasang, da me a pan kanomanom mau kida?',
        35: 'A solar mau ong nan sap, pil so nan pwel, pwe aramas kin kasela. Me salong a mia men rong, i en rong!',
    },
    15: {
        1: 'A SAUNOPWEI o me dipan akan karos ap kai dong i pwen rong i.',
        2: 'A Parisär o saunkawewe kan lipaned indada: Ol men et kin kompokeki me dipan akan o iang irail sakasak.',
        3: 'A a kotin masani ong irail karaseras wet:',
        4: 'Is aramas re omail me na sip epuki, a ma amen irail salongalar me so pan pwilikidi ir duekduemen nan wel ap raparapaki me salongalar, lao a pan diarada i?',
        5: 'A lao diarada i, a kidang pon pop a pereperen.',
        6: 'A lao pure dong deu a, a kin eker pena kompokepa kan o men imp a kan indai ong irail: Komail iang ia perenda, pwe i diaradar nai sip me salongalar.',
        7: 'I indai ong komail, nan iduen peren pil pan mi nanlang pweki me dipan me ta men, me kalula, sang duekduemen me pung ap sota mau ong kalula.',
        8: 'O is li o me na denar eisok, eu ap salongala sang, me so pan isikada lamp o koke im o, o raparapaki mau, lao a pan diarada?',
        9: 'A lao diaradar i, a kin eker pena kompokepa kan o men imp a kan indai ong irail: Komail iang ia perenda, pwe i diarada ai denar o, me salongalar.',
        10: 'Nan I indai ong komail, iduen peren mi ren tounlang en Kot akan, pweki me dipan me ta men, me kalula.',
        11: 'A kotin masani: Aramas amen mia, me na ol riamen.',
        12: 'A me tikitik re’ra indai ong sam a: Sam ai, kotiki dong ia pwais ai en soso, me udan ai. I ari nene ong ira ara dipisou kan.',
        13: 'A murin ran akai me tikitik ren ol oko ki pena a dipisou karos, ap sailokalang sap doo, wasa a kasela mal a kapwa kan nin tiak sued.',
        14: 'A lao kamuse weita a kapwa karos, lek lapalap ap pwaida sap o, i ari dupokalar.',
        15: 'I ap koieila dodok ren me pweledan sap o men. I ap kadarala i, pwen kamanga na pwik kan.',
        16: 'I ari inong iong, kangkang wantuka kai, me pwik kin namenam, a sota me mueid ong i.',
        17: 'A kadekadeo i lao lolekongalar, ap indada: Ladu me depa mi ren sam ai, me kan ar manga me rak, a ngai pan mekila so kan ai manga.',
        18: 'I pan uda purela ren sam ai indai ong i: Sam ai, i wiadar dip ong nanlang o ong komui.',
        19: 'I solar warong adaneki noumui putak, komui ari wia kin ia ladu’mui men.',
        20: 'I ari uda purela ren sam a. A ni a mi wasa doo, sam a kilangada i, ap pokela, pitipiti dong i o polodi i, metik i.',
        21: 'A putak o indai ong i: Sam ai, i wiadar dip ong nanlang o ong komui, i solar war ong adaneki noumui putak.',
        22: 'A sam masani ong na ladu kan: Wado likau kasampwal o kalikauwia kida i, o ki ong ring ni sondin pa a, o sut ni nä a kan.',
        23: 'O wado kau pul wi o kamela, pwe kitail en kang o pereperen.',
        24: 'Pwe nai putak men et melar ap mauredar, a salongalar ap diarokadar. Irail ari perendar.',
        25: 'A na putak laud mi nan sap o. Ni a pure dong koren iong im o, ap rongadar kakaul o kakalek,',
        26: 'Ap kalelapok ren ladu men duen ar wiawia.',
        27: 'A indang i: Ri omui ol puredo, sam omui ap kamela kau pul wi o, pwe a diaradar i memaur o kelail.',
        28: 'A ap makara kida o sota men pedelong, sam a ap pedoi dong re a poekipoeki.',
        29: 'A a sapeng indang sam a: Kom mangi, par toto me i papa komui, o i saikenta kawela eu omui masan akan, a kom sota kotiki ong ia kisin kut amen, i en kamadipeki kompoke pai kan.',
        30: 'A noumui putak men et lao kodo, murin a kamuse wei a dipisou ren me sued akan, komui ap isik ong i kau pul wi o.',
        31: 'Sam a ap masani ong i: Nai seri, koe kin mimieta re i ansau karos, o ai meakaros me om.',
        32: 'Me mau, koe en peren o insenemau. Pwe ri om ol men et melar, ap mauredar, a salongalar ap diarokadar.',
    },
    16: {
        1: 'A PIL kotin masani ong tounpadak kan: Ol kapwapwa men mia, me a saunkoa men indandeki, a peitlakit a koa kapwa kan.',
        2: 'I ari eker dong i indang i: Iaduen ai rongadar duen koe? Kaineneta noum kisin likau duen om dodok! Pwe koe solar kak saunkoa.',
        3: 'Saunkoa ap madamadaua indada: Da me i en wia, pwe ai monsap pan ki sang ia ai koa, nan i sota kak weweir, a poekipoeki me i namenokki.',
        4: 'I ap asada, me i pan wia, i lao sapwilidi sang ai koa, pwe irail en kasamo ia long ong nan im ar akan.',
        5: 'I ari ekeredo me pwaipwand ong a monsap, ap idok ren men mas: Da me om pwaipwand ong ai monsap?',
        6: 'A inda: Potel en le epuki. A indai ong i: Ale noum puk mondi pitipit intingiedi me limeisok!',
        7: 'Ap pil indai ong amen: A koe, da me om pwaipwand? A inda: Kopa en wan korn epuki. A indang i: Ale noum puk intingiedi me waleisok!',
        8: 'Monsap ap kapinga saunkoa sapung, pweki a dodok lolekong. Pwe seri en sappa kan me lolekong ni song ar sang seri en marain akan.',
        9: 'I ap indai ong komail, komail wia kompoke pamail ki mamon sapung pwe komail lao samamalar, ren kasamolong ong nan deu potopot.',
        10: 'Meamen apwali mau me tikitik o, nan i me pil kin apwali mau me lapalap. A me kin sapung ni me tikitik o, nan i me pil sapung ni me toto.',
        11: 'Ma komail sota apwali mau pai pali pa, is me pan liki ong komail pai pali poa?',
        12: 'O ma komail sota apwali mau en amen a kapwa, is me pan liki ong komail me udan omail?',
        13: 'Sota ladu men me pan kak papa saumas riamen; pwe a pan kailongki amen o pok ong me teio. De kasampwaleki amen o mamaleki me teio. Komail sota pan kak pariai pena Kot o mamon.',
        14: 'Parisär akan, me kin pok ong moni, pil rongadar mepukat, ap kaurureki i.',
        15: 'A kotin masani ong irail: Nan komail me kin akapungki pein komail ren aramas, a Kot kin mangi nan mongiong omail. Pwe me kasampwal ren aramas, kin me mal ren Kot.',
        16: 'Kapung o saukop akan kokoper lel ni muein Ioanes. A sang ni ansau o rongamau en wein Kot kin lolok sili, a karos kin pedelongki manaman.',
        17: 'Nan me mongai, lang o sappa pan sorela, sang ekis kisan kapung en lokidokila.',
        18: 'Meamen kasela a paud, ap paudeki amen li, nan i me kamal, o meamen me paudekida me lokidokila sang ren ol amen, nan i me kamal.',
        19: 'Ol kapwapwa men mia, me a likau waitata o materok o a kin kamadip o peren ni ran karos.',
        20: 'O pil amen ol me samama, ad a Lasarus, me kin wonon pan wanim en ol kapwapwa o; a kensela kili karos.',
        21: 'Ap men tungole maremor akan, me kin pupedi ni tepel en me kapwapwa; a kidi kan kin tamotamo a kens akan.',
        22: 'A kadekadeo me samama o mela o tounlang kai ap wadala pon kapa en Apraam. A me kapwapwa o pil mela o saredier.',
        23: 'Ni a mi nan pweleko, wasan waiwairok, ap sarada, udial Apraam ni wasa doo o Lasarus mondi pon kapa,',
        24: 'Ap likwirda indada: Sam (ai) Apraam, kom kotin kupura ia, poronedo Lasarus en kaduedi sondin pa a nan pil, ki ong pon lo i, pwe i kin waiwairok nani iai wet.',
        25: 'A Apraam kotin masani: Nai, tamanda, me koe tungoler om mau kan karos ni maur om, a Lasarus a me sued akan; ari a pan pereperenta, a koe pan kalokolok.',
        26: 'A pil eu me kawela, wau kalaimun eu mi nan pung atail, pwe ma amen kit men sapale wong re omail, a sota pan kak, pil sota amen komail pan kakedo.',
        27: 'A ap inda: I ap men poeki, sam ai, komui en kotin poronelang Lasarus nan im en sam ai.',
        28: 'Pwe ri ai ol me limen, me a pan kaasaki irail; pwe ren de lel ong wasa apwal wet!',
        29: 'A Apraam masani ong i: Moses o saukop akan mi re’rail, ren nok rong irail.',
        30: 'A ol o potoan ong: Kaidin sam (ai) Apraam, a ma amen sang ren me melar akan pan pwara dong irail, rap pan kalula.',
        31: 'A ap masani ong i: Ma re sota pan rong Moses o saukop akan, re pil sota pan poson la, ma amen pan maureda sang ren me melar akan.',
    },
    17: {
        1: 'A KOTIN masani ong sapwilim a tounpadak kan: Nan a sota kak, men kamakar kan en so pwaida, a suedi ong me kokido.',
        2: 'A mau ong, takai en ir plaua eu en paudoki ong ni tapin wor a, ap lokidokila nan madau, sang a kamakar amen tikitik pukat.',
        3: 'Kalaka pein komail! Ma ri om ol wia dipi ong uk, en kapung ong i, a ma a pan kalukila, maki ong i.',
        4: 'A ma a wia dipi ong uk pan isepak ni ran eu o pure dong uk pan isepak indada: I kalula, koe en maki ong i!',
        5: 'A wanporon akan potoan ong Kaun o: Re kotin kalaudela at poson!',
        6: 'A Kaun o kotin masani: Ma omail poson laudi ong wan katiring, komail pan kak indai ong tuka pik pot et: Kaisang, kasau ong nan madau, a pan oke komail.',
        7: 'A is re omail, me a ladu men, me kin matimat o kamakamanga man akan, pan indang i ni a puredo sang matuel o: Madang kodo mondi o manga?',
        8: 'A sota pan indang i: Kaonopada me i pan manga nin sautik o, kaiada om likau, papa ia, lao i mangaer o nim, a muri koe pan manga o nim.',
        9: 'De a pan danke ladu pweki a wiada, me a masani ong i? I lamelam so.',
        10: 'Pil dueta komail, komail, lao wiadar meakan me kakaliki ong komail er, komail ap pan inda: Kit ladu mal, pwe i eta, me se wiadar, me kakalik ong kit er.',
        11: 'Kadekadeo ni a kotilang Ierusalem, a kotin weid nan wein Samaria o Kaliläa.',
        12: 'O ni a kotin kotilong ong nan kisin kanim eu, ol tuketuk ek tu ong i, me udi ong kaila wei.',
        13: 'Irail ngil laudeda indada: Maing Iesus, kupurai kit!',
        14: 'A lao kotin masanier, ap masani ong irail: Komail koieila kasansale ong pein komail ong samero kan. Kadekadeo ni arail kokola irail kelailada.',
        15: 'A amen irail ni a kilanger me a kelailadar, ap puredo ngil laudeda, kapikapinga Kot.',
        16: 'O poridi sang aluwilu a, danke i; ari, i men Samaria men.',
        17: 'Iesus kotin sapeng masani: Kaidin me ek, me kelailadar, a ia me duemen oko?',
        18: 'Sota me pure dong kapinga Kot, ol en liki men et eta?',
        19: 'A masani ong i: Uda ko wei, om poson me kakel uk ada!',
        20: 'Parisär akai lao kalelapok re a: Dokan da me wein Kot pan pwaida? A kotin sapeng masani: Nan wein Kot sota kin sansal kokodo.',
        21: 'Irail sota pan indada: Kilang met, de kilang monen, pwe kilang, wein Kot mi lol omail.',
        22: 'A kotin masani ong sapwilim a tounpadak kan: Ran oko pan kodo, me komail pan men kilangada ran eu en Nain aramas, a komail sota pan kak kilang.',
        23: 'Irail pan indai ong komail: Kilang monen, de kilang met! A der kola o der idauen ir ala!',
        24: 'Pwe duen liol kin lingaling sang apali en lang lel pali teio en lang, iduen Nain aramas ni a ran o.',
        25: 'A mas a pan kalokolok toto o lokidokila ren di wet.',
        26: 'O duen a wiaui ni muein Noa, iduen a pan wiaui ni ran oko en Nain aramas:',
        27: 'Irail manga, irail nim, irail papaud, irail kapapaud, lao lel ran en Noa a pedelong ong nan war im o, o nolik pwaida kamom ir ala karos.',
        28: 'Pil dueta ni muein Lot: Irail manga, irail nim, irail netinet, irail sapasap, irail kauadar im,',
        29: 'A ni ran o, me Lot koiei sang Sodom, kisiniai o swepel ap moredi sang nanlang, kame ir ala karos.',
        30: 'Nan iduen a pan wiaui ni ran, me Nain aramas pan sansaledo.',
        31: 'Ni ran o meamen mi pon im, o a kapwa mi nan im, a ender kodi ong ale. O pil dueta me mimi nan sap, i ender puredo.',
        32: 'Tamatamanda en Lot a paud!',
        33: 'Pwe meamen kanakanai ong maur a, pan pupe sang, a me pan kasela, nan i me pan maureta.',
        34: 'I indai ong komail, ni pong ota ol riamen pan wonon pon pet eu, amen pan peuka sang, a me teio pan mimieta.',
        35: 'Li riamen pan iris pena plaua, amen pan peuka sang, a me teio pan mimieta.',
        36: 'Ol riamen pan mi nan sap, amen pan peuka sang, a me teio pan mimieta.',
        37: 'Irail sapeng potoan ong i: Ia Maing? A kotin masani ong irail: Wasa me man mat mi ia, nan i wasa pwin ikel pan pil pokon pena ia.',
    },
    18: {
        1: 'A PIL kotin masani ong irail karaseras eu, me ren poden kapakap o der pangada.',
        2: 'A kotin masani: Saunkapung amen mi nan kanim eu, me sota lan Kot, o sota insenoki aramas amen.',
        3: 'A li odi men mi nan kanim ota, me poto dong i potoan ong: Kom kotin sauasa ia ong me kailong kin ia!',
        4: 'A a kang mas o, a kadekadeo a mongemongeloleki: Nan i sota lan Kot, o pil sota insenoki aramas,',
        5: 'A pweki li odi men et a kadiropa ia, i pan sauasa i, pwen der purodo kadiropa ia.',
        6: 'Kaun o ap kotin masani: Komail rong, me saunkapung sapung indada!',
        7: 'A iaduen Kot, a sota pan kotin sauasa sapwilim a pilipildar akan, me kin likelikwir ong i ni ran o ni pong? Pala a pan kotin pwapwand?',
        8: 'I indai ong komail: Nan a pan madang sauasa ir. Ari so, Nain aramas lao pwarado, da, a pan diar poson ni sappa?',
        9: 'A pil kotin karasai ong irail me kin akapungki pein irail, ap akasapungki me tei kan:',
        10: 'Aramas riamen kodala ong nan im en kaudok pwen kapakap. Amen ira Parisär, a amen saunopwei men.',
        11: 'Parisär o kasinenda kelepela ekis wasa kapakap due met: Maing Kot, i danke ir, me i sota dueta aramas tei kan: Lolap, sapung, kamal, de dueta saunopwei men et.',
        12: 'I kin kaikaisole pan riapak ni wik eu o koleireki eisokkis eu en ai kapwa karos.',
        13: 'A saunopwei u doo sang ekis wasa, ap sota men sarada nanlang, a a pikir maramar a indada: Maing Kot, re kotin kupura ia me dipan!',
        14: 'I indai ong komail, ol men et kodila deu a pungala mon me teio. Pwe me kin kasapwilada pein i, pan kasapwilidi, a me kin kasapwilidi pein i pan kasapwilada,',
        15: 'Irail ap wa dong i kisin seri kai, pwen kotin sair ir. A sapwilim a tounpadak kan lao kilanger, re ap kapoui irail.',
        16: 'A Iesus kotin molipe ir masani: Mueid ong kisin seri kan, en kodo re i! Der kalik irail edi! Pwe irail me udan wein Kot.',
        17: 'Melel I indai ong komail, meamen, me sota ale wein Kot rasong kisin seri men, a sota pan pedelong ong lole.',
        18: 'A monsap amen idok re a masani: Saunpadak mau, da me i en wiada, pwen sosoki maur soutuk?',
        19: 'Iesus ari kotin masani ong i: Da me koe indaki, me I me mau? Sota me mau men, Kot eta.',
        20: 'Koe kin asa kusoned akan: Koe der kamal; koe der kamela aramas; koe der pirap, koe der kinekine mal, kakaki sam om o in om!',
        21: 'I ari indada: Nan mepukat karos i kin wiawia sang ni ai tikitik kokodo.',
        22: 'Iesus lao mangi mepukat, ap masani ong i: Me ta kis me lua, netikila om kapwa karos, o nene ong me samama kan, a om pai pan mi nanlang, ap kodo idauen ia do.',
        23: 'A lao rongadar met, ap insensuede kila melel, pwe a kapwapwa kaualap.',
        24: 'A Iesus lao kotin masani, me a insensuedela, ap masani: Nan me apwal ong me kapwapwa kan, en pedelong ong nan wein Kot.',
        25: 'Pwe me mangai, kamel en tilong nan por en dikok, sang ol kapwapwa men pedelong ong nan wein Kot.',
        26: 'Irail me rongerong indada: Ari, is me kak ong maur?',
        27: 'A kotin masani: Me aramas akan so kak ong, Kot me pan kak ong.',
        28: 'Petrus ap potoan ong: Re kotin mangi, kit me likid maliela meakaros ap idauen la ir.',
        29: 'A kotin masani ong irail: Melel I indai ong komail, nan sota me likidmaliela im a, de sam, de in a, de ri a ol akan, de a paud, de na seri kan pweki wein Kot,',
        30: 'Me so pan id aneki me lapalap ni ansau wet o ni muei kokodo maur soutuk.',
        31: 'A kotin ukala ekriamen ko masani ong irail: Kilang, kitail kin kodalang Ierusalem, o karos pan pwaida, me intingidier ren saukop akan duen Nain aramas.',
        32: 'Pwe a pan pangala ren men liki kan, pwe re pan kapikapiti i o ki sang wau i, o kondipi ong i.',
        33: 'O re pan woki i o kamela, a ni kasilu en ran a pan maureda.',
        34: 'Irail ari sota man weweki mepukat, O masan pot et me rir sang irail. Re pil sasa, me a kotin masani.',
        35: 'A kadekadeo ni a koren iong Ieriko, ol maskun amen momod pon kailan al, poekipoeki.',
        36: 'I lao rongadar pokon o me daudaulul, ap idok due.',
        37: 'Irail ari indang i, me Iesus men Nasaret kotin daulul.',
        38: 'I ari ngil laudeda potoan ong: Iesus, sapwilim en Dawid, kotin kupura ia!',
        39: 'A me tiong moa kidekidaue i, en nenenla: A i ap kalaudela a poekipoeki: Sapwilim en Dawid, kotin kupura ia!',
        40: 'Iesus ap kotin udi ong wasa o, masani, ol o en wisike dong i. A lao koren iong imp a, ap kotin kainoma re a.',
        41: 'Masani: Da me koe men, I en wiai ong uk? A potoan ong: Maing, i men potoan ngarada wasa.',
        42: 'A Iesus kotin masani ong i: Kilang wasa, om poson me kakel uk ada!',
        43: 'Ap pitipit kilangada wasa, o idauenla i, o kapinga Kot, o aramas karos, me udial met, ap kapikapinga Kot.',
    },
    19: {
        1: 'I ARI kotilong ong nan kanim Ieriko, ap kotin daulula.',
        2: 'A kilang, ol kapwapwa men mia, ad a Sakäus, me saumas en saunopwei kan.',
        3: 'A men kilang Iesus, pwen asa, is i, ap sota kak, pweki pokon o, o a sakakair.',
        4: 'I ari tiong mo’rail, dauda nin tuka pot, pwen kak kilang i, pwe a pan kotin daulul wasa o.',
        5: 'A lao lel wasa o Iesus ap kotin masanda diar i, masani ong i: Sakäus, madang daudi, pwe I pan pedelong ong nan im om ran wet.',
        6: 'I ari madang daudi kasamo i pereperen.',
        7: 'Irail lao kilanger met, karos ap lipanedeki inda: A pedelonger, pwen kairu ren ol dipan amen.',
        8: 'A Sakäus potodo potoan ong Kaun o: Maing re kotin mangi, apali en ai kapwa i pan kisakisaki me samama kan, o ma i kotaue amen, i kin kasapal wong i pan pa pak laude sang.',
        9: 'Iesus kotin masani ong i: Maur me pwara dong nan im wet ran wet, pwe a pil nain Apraam amen.',
        10: 'Pwe Nain aramas pwara don rapaki o kamaureda me salongalar.',
        11: 'A ni ar rongadar mepukat, a pil kotin masani karaseras eu, aki koren iong Ierusalem, o re kiki ong, me wein Kot pan madang sansaleda.',
        12: 'A kotin masani: Ol lapalap amen kolang sap doo eu, pwen nine mar a, ap pan puredo.',
        13: 'I me eker pena na ladu ek, o ki ong irail paun eisok, indang irail: Komail dodokki, i lao puredo.',
        14: 'A na aramas akan kailongki i, kadarala mur i kaireki lang i: Se sota mauki, ol men et en kaun kit.',
        15: 'Kadekadeo a lao puredo, murin a aleer wei o, ap ilakelang ladu kan, me a ki ong na moni, pwen asa duen en amen amen ar kalaudelar na moni.',
        16: 'Men mas ap pwarado indada: Maing, omui paun kareda paun eisok.',
        17: 'A indang i: Meid pai ladu mau koe, aki om apapwali mau me tikitik, koe pan id kaunda kanim eisok.',
        18: 'O kariamen ap pwarado indada: Maing, omui paun me kareda paun limau.',
        19: 'A pil indang i: Koe pan kaunda kanim limau.',
        20: 'O pil amen pwarado indada: Maing, mangi, ietet sapwilim omui paun, me i nekidala nan lim en pudo.',
        21: 'Pwe i masak komui, pwe ol petik amen komui. Komui kin aleda, me kaidin komui kidier, o dolung sang, me kaidin komui padukedier.',
        22: 'A indang i: Sang nan au om i pan kadeik kin uk ada ladu sued koe. Koe asaer, me ol petik amen ngai, me kin ale, me kaidin ngai kidier o dolung sang, me kaidin ngai padukidier.',
        23: 'Menda koe sota wala nai moni wasan kanaitik, o i lao puredo, i pan ale me udan ai iangaki moni naitik.',
        24: 'A indai ong irail me u impa: Ale sang i paun o, ki ong ren me a paun eisok!',
        25: 'Irail indai ong i: Maing, nan a nainekier paun eisok.',
        26: 'Pwe I indai ong komail, meamen, me a mia, ekis pan ko ong, a me sota a mia, nan a pwitikatik pil pan katia sang.',
        27: 'A ir, ai imwintiti, me kang, i en kakaun ir, wa ir do, o kame ir ala mo i!',
        28: 'A lao kotin kaimwisokala a masan pukat, ap kotiwei kotidala Ierusalem.',
        29: 'Kadekadeo a lao koti dong Petpake o Petanien impan dol me ad a Oliwe, ap kotin poronela sapwilim a tounpadak riamen,',
        30: 'Masani: Koma ko ong nan kanim monen, koma lao pedelong, koma pan diarada esel pul amen salidi, me aramas amen saik mondi poa. Lapwada i, ap karedo!',
        31: 'A ma meamen pan idok re oma: Da me koma lapwa kida i? Koma ap pan inda: Kaun o men dake.',
        32: 'A ira me pakadara wei, ap kola o diarada, duen a kotin masani ong ira.',
        33: 'A ni ara lawada esel pul o, ol oko, me naineki, ap indang ira: Da me koma lawa kida esel pul en?',
        34: 'Ira ap indada: Kaun o men dake.',
        35: 'Ira ari wado ren Iesus, ap irepadi pon esel pul arail likau kan ap potoan dang Iesus poa.',
        36: 'Ni a kotikot kokowei, irail ap irepakidi arail likau kan nani al.',
        37: 'A lao kotin korendor kotidila dol Oliwe tounpadak kan karos ap wiaki eu ngil laudeda kapinga Kot, pweki manaman akan karos, me re kilanger,',
        38: 'Indada: Kapinga ong Nanmarki, me kotido ni mar en Kaun! Nanlang en popol o lingan wasa ileile!',
        39: 'A Parisär kai kisan pokon o indai ong i: Saunpadak, kotin kidaue sapwilim omui tounpadak kan.',
        40: 'I ari kotin sapeng masani ong irail: I indai ong komail, ma mepukat pan nenenla, takai pan id kadededa.',
        41: 'A lao kotin korendor, ap masani kanim o, ap tontonireki,',
        42: 'Masani: O i men, koe en dedeki om ran mau wet, me pan kare ong uk popol: Ari, a rir sanger mon mas om.',
        43: 'Pwe ran apwal ko pan lel ong uk, me om imwintiti pan kele kin uk pena o it pena sang ni pali karos;',
        44: 'O irail pan kase uk ala iangaki noum seri kan, o re pan karongk uk ala; sota eu takai pan mimieta pon eu, pweki om sota dedeki ansaun om kasosong.',
        45: 'I ari kotilong ong nan im en kaudok, ap sikon sang me netinet lole,',
        46: 'Masani ong ir: Nan a intingidier: Im ai im en kapakap, a komail wiaki deun lolap akan.',
        47: 'I ari kotin kaukawewe nan im en kaudok ran karos. A samero lapalap, o saunkawewe, o me lapalap akan ren aramas raparapaki, en kamatala i.',
        48: 'A re sota kak diar, me ren wiada, pwe aramas karos apwali i kaualap o men rong i.',
    },
    20: {
        1: 'KADEKADEO eu ran ni a kotin kawewe ong aramas akan nan im en kaudok o, o padaki rongamau, samero lapalap, o saunkawewe, iangaki saumas akan ap ko dong i.',
        2: 'Potoan ong i indada: Masani ong kit, manaman en is, me komui wiaki mepukat? De is me ki ong komui manaman wet?',
        3: 'A kotin sapeng masani ong irail: I pil pan kalelapok meakot re omail, komail en sapeng ia!',
        4: 'En Ioanes a paptais men nanlang, de me ren aramas?',
        5: 'Irail ap lamelame nan pung arail indada: Ma kitail pan inda, men nanlang, a pan masani ong kitail: Da me komail so posonki i?',
        6: 'A ma kitail inda, me ren aramas, aramas karos ap pan kate kit, pwe re kin wia saukopki Ioanes.',
        7: 'Irail ari sapeng, me re sasa, wasa me a kosang ia.',
        8: 'Iesus ap kotin masani ong irail: Ari, I pil sota pan indai ong komail, manaman en is, me I wiaki mepukat.',
        9: 'A ap kotin tapiada masani ong pokon o karaseras wet: Aramas amen padukedier mat en wain eu, ap liki ong saumat akai, o kokola nan wai ansau warai.',
        10: 'A lao ansau, a kadaralang saumat akan ladu men, pwe ren ki ong kisan wan wain. A saumat akan woki i, o kadarala i kaip.',
        11: 'A murin met a pil kadarala amen ladu, a re pil woki i, o wia suedi ong, o kadarala i kaip.',
        12: 'A murin met a kadarala kasilimen. A re pil kame i o siken wei sang.',
        13: 'Monsap en mat en wain o ap masani: Da me i en wiada? I pan kadarala nai ol kompok, ele re pan masak, ni ar pan kilang i.',
        14: 'A saumat akan lao kilanger i, rap lamelame nan pung ar indada: Iei i, me pan ale soso, kitail pan kamela, pwen id aneki a soso.',
        15: 'Irail lao kasapoka sang i nan matuel o, ap kamela i. Da me monsap en mat en wain pan wiai ong irail?',
        16: 'A pan kodo kamela saumat pukat, ap liki ong akai a mat en wain. Irail lao ronger mepukat, rap indada: O mepukat sota pan wiaui!',
        17: 'A kotin saupei wong irail ap kotin masani: Iaduen wewe en inting wet: Takai o, me sause kasapokela, id wiala takai en pukakaim?',
        18: 'Meamen, me pupedi pon takai wet pan ola. A me a pupedi ong poa, a pan kapitaka pasang i.',
        19: 'I dokan o saunkawewe o samero lapalap akan raparapaki en saikidi i. A re masak aramas akan, pwe re muilikiada, me a karaseras kin irail.',
        20: 'Irail ari masamasan i o kadarala liparok kai, me pan wia kin pein irail aramas pung, pwe ren saikikidi i a masan akan ap pangalang saunkapung o manaman en kopina.',
        21: 'Irail ari kalelapok re a potoan ong: Saunpadak, kit potoan asa, me ar masan o padak kan me pung, o re sota kotin kupuroki sansal en aramas. Pwe re kin kotin kaukaweweda melel duen al en Kot.',
        22: 'Me pung kit en nopwei ong nanmarki, de so?',
        23: 'A i kotin mangi ar widing, ap masani ong ir: Da me komail kasongesong kin ia?',
        24: 'Kasale dong ia denar eu! Mom en is o inting wet? Re sapeng potoan ong: En nanmarki.',
        25: 'A i kotin masani ong irail: Ari komail ki ong nanmarki, me nain nanmarki, o ong Kot, me sapwilim en Kot!',
        26: 'Irail ari sota kak saikikidi i a masan akan mon pokon o. Irail puriamuiki me a kotin sapeng, o nenenlata.',
        27: 'Sadusär akai, me kin inda, me dene melar akan solar pan maureda, ap kai dong i kalelapok re a,',
        28: 'Potoan ong: Saunpadak, Moses intingie dong kit, ma ri ol en amen pan mela, me a paud li dapwan men, ri a ol ap pan paudekida i, pwen kaipwi ong ri a ol na seri kai.',
        29: 'Ari, pwin pirien, ol isimen mia, men mas paudeki li amen, ap mela, a sota na seri ko.',
        30: 'A kariamen paude kida li o ap mela a sota na seri ko.',
        31: 'A kasilimen paude kida i, iduen ir isimen karos, re mela, ap sota nairail seri ko.',
        32: 'A ikmuri li o pil mela.',
        33: 'Ari, ni en me melar akan ar iasada, a pan en is a paud? Pwe ir isimen karos paude kida i.',
        34: 'Iesus kotin masani ong irail: Seri en sappa et kin papaud o kapapaud.',
        35: 'A me war ong ale eu sap o konodi maureda sang ren me melar akan, re sota kin papaud de kapapaud.',
        36: 'Pwe re pil solar kak mela. Pwe re paroki ong tounlang kan, o re seri en Kot akan, pwe re seri en kamaur.',
        37: 'A duen en me melar akan ar pan maureda, Moses pil kadededa, ni a udial tuka o, ni a kaadaneki Kaun o: Kot en Apraam, o Kot en Isaak, o Kot en Iakop.',
        38: 'Pwe Kot kaidin Kot en me melar akan, a en me maur akan, pwe karos memaur ong i.',
        39: 'A Saunkawewe kai sapeng indada: Saunpadak, ar masan me pung.',
        40: 'Irail ap solar kak peidok re a okotme,',
        41: 'I ari kotin masani ong irail: Iaduen ar indinda, me Kristus nain Dawid?',
        42: 'A pein Dawid katitiki nan puk en Psalm: Kaun o kotin masani ong ai Kaun: Mondi ong ni pali maun i.',
        43: 'Lao I pan wia kida om imwintiti utepan nä om.',
        44: 'Dawid ari wia kin i a Kaun, a iaduen a pan kak na ol?',
        45: 'A ni aramas karos rongadar, a kotin masani ong sapwilim a tounpadak kan:',
        46: 'Kalaka saunkawewe kan, me kin mauki momait sili nan likau reirei o mauki, aramas en ranamau ong irail nan wasa en netinet akan, o men mondi leppantam nan sinakoke kan o ni tapin tepel.',
        47: 'Me kin ngopur im en li odi kan, liasoski kapakap reirei, mepukat pan pangalang kadeik apwal.',
    },
    21: {
        1: 'A KOTIN aupwil sili ap masani, me kapwapwa kan kasedi ong ar mairong nan deun mairong.',
        2: 'A pil kotin masani, me li odi samama men kasedi ong lepta riau.',
        3: 'A kotin masani: Melel I indai ong komail, li odi samama men et kasedi ong laude sang irail karos.',
        4: 'Pwe mepukat karos kasedi ong mairong en Kot sang ni ar pai, a li men et kasedi sang ni a samama, a dipisou karos, me a naineki.',
        5: 'Akai lao kasokasoiadar duen im en kaudok, me kapwata kida takai kasampwal akan o kapwa en mairong kai, ap kotin masani:',
        6: 'Ran oko kokodo, karos, me komail ududial, pan karangk pasang, sota eu takai pan mi pon eu.',
        7: 'Irail kalelapok re a potoan ong: Saunpadak iad mepukat pan pwaida? O da pan kilel en mepukat pan wiaui?',
        8: 'A kotin masani: Komail kalaka, pwe meamen de kotaue komail! Pwe me toto pan kodo ni ad ai o pan inda: Ngai i o ansau korendor! A komail der idauen ir ala.',
        9: 'A komail lao rong duen mauin o muei sued, ender masak, pwe mepukat pan wiaui mas, a saikenta imwi.',
        10: 'A kotin masani ong irail: Toun sap eu pan u ong eu sap, o wei eu pan u ong eu wei.',
        11: 'O rerer laud en sap akan pan wiaui, o lek, o song en somau pan pwaida, o pil sansal kamasapwek kai, o kilel lapalap akan pan pwarada sang nanlang.',
        12: 'A mon mepukat re pan saik komail edi, o kame komail, o panga komail la nan sinakoke kan o imateng pwen kalualang ren nanmarki o saumas akan pweki ad ai.',
        13: 'A mepukat pan wiaui ong komail, pwen kadede kin ia.',
        14: 'Komail ari inauki ong pein komail nan mongiong omail, me komail sota pan patauki, me komail pan sapengki.',
        15: 'Pwe ngai me pan kalokaia komail, o kalolekongla, pwe me kailong kin komail, en sota kak kalikama, o so palian.',
        16: 'A sam o in omail, o ri ol akan, o sau omail, o kompokepa kan pan panga komail la, o akai komail me re pan kamela.',
        17: 'O aramas karos pan kailong kin komail pweki ad ai.',
        18: 'A sota pit en mong omail pit pan lokidokila.',
        19: 'Dore kila kanongama maur omail:',
        20: 'A komail lao udial, me saunpei kan kapili pena Ierusalem, komail ap asaki, me a ola korendor.',
        21: 'A me mimi Iudäa, ni ansau o, en tangdala nan nana; o me mi nan warong a, en pitila sang; o me mimi nan sap, ender purelang i.',
        22: 'Pwe i ansaun depuk, pwe karos, me intingidier, en pwaida.',
        23: 'Suedi ong me lisean o me kadidi seri ni ran oko! Pwe kalokolok pan lapalapia nan sap et o ongiong ong aramas pukat.',
        24: 'O re pan kame kila kodlas, o salilang wei karos, o Ierusalem pan tiak pasang ren men liki kan, lao ansau en men liki kan, pan lel.',
        25: 'O kilel akan pan wiaui ni katipin, o saunipong, o usu kan, o aramas nan sappa pan masak o pan pingidar, o madau o iluk kan pan angiang ngil laudeda;',
        26: 'O aramas akan pan okila ar masak o auiaui me pan wiaui nan sappa; pwe kel en lang akan pan mokideda.',
        27: 'Irail ap pan kilangada Nain aramas a kodido ni dapok ki roson o lingan kaualap.',
        28: 'Mepukat lao pikikidi wiaui, komail ap sarada o kasinenda, pwe a leler omail kamaioda.',
        29: 'A kotin masani karaseras eu ong irail: Kilang tuka pik o tuka karos!',
        30: 'Ni omail kilang me irail wiliada, komail kin asaki, me rak o me korendor.',
        31: 'Iduen komail, komail lao kilang mepukat lao wiaui, komail asaki, me wein Kot korendor.',
        32: 'Melel I indai ong komail, di wet sota pan imwila mon mepukat karos pan pwaida.',
        33: 'Lan o sappa pan sorela, a ai masan akan sota pan poula.',
        34: 'Komail ari kalaka pein komail, pwe mongiong omail de toutouki kaped en manga, o kamom sakau, o ngongongki maur et, o ran o ap madang lel dong komail.',
        35: 'Pwe likamata insar eu, a pan ko dong karos, me kin kakauson sappa.',
        36: 'Komail ari masamasan o poden kapakap, pwe komail en war ong en piti sang mepukat karos, me pan wiaui, o en pat ong Nain aramas.',
        37: 'Ni ran o a kotin kaukawewe nan im en kaudok o, a ni pong a kotieila kotikot pon dol o me adaneki Oliwe.',
        38: 'O aramas karos sangkonai pokon dong i nan im en kaudok o, pwen rong i.',
    },
    22: {
        1: 'A KAMADIP en prot somut korendor, me adaneki pasa.',
        2: 'Samero lapalap o saunkawewe kan raparapaki, pwen kamatala i, pwe irail masak aramas akan.',
        3: 'A Satan tilong ong Iudas me adaneki Iskariot, me kisan ekriamen ko.',
        4: 'I ari koieila ren samero lapalap o saumas akan, kalelapok duen a pan pangalang ir i.',
        5: 'Irail ari peren kida, wiaki eu en ki ong i moni.',
        6: 'I ari inauki ong irail, o raparapaki, duen a pan pangalang ir i so moromorong.',
        7: 'Ran en prot somut ap leler, ansaun kamela pasa.',
        8: 'I ari poronela Petrus o Ioanes masani: U kowei, kaonopadang kitail pasa, pwe kitail en manga.',
        9: 'Irail idok re a: Ia wasa, re kotin kupura, sen kaonopada?',
        10: 'A kotin masani ong irail: Kilang, koma lao pedelong kanim o, aramas amen pan tu ong koma, me wa pakit en pil eu, idauen i nan im o, me a pedelong ong lole!',
        11: 'Koma ap indang kaun pan im o: Saunpadak o masanie dong komui: Ia pera en kairu, wasa I pan manga pasa ia iangaki ai tounpadak kan?',
        12: 'I ari pan kasale ong koma weip poa eu, me audeki men momod, i wasa koma pan kaonopada!',
        13: 'Ira lao koieila, ap diarada, duen a kotin masani ong ira; ira ap kaonopada pasa.',
        14: 'Auer lao leler, i ap kaipokedi ni tepel o wanporon ekriamen iang i.',
        15: 'I ap kotin masani ong irail. I anane melel iang komail manga pasa wet mon ai pan kalokolok.',
        16: 'Pwe I indai ong komail, I solar pan kang sang met kokolata, a lao kapungala nan wein Kot.',
        17: 'I ari kotikida dal o laolaoki ap masani: Ale met, nek nan pung omail!',
        18: 'Pwe I indai ong komail, I solar pan nim sang kisan wan wain, wein Kot lao pwaidar.',
        19: 'A kotin limada prot, laolaoki o pilitiki pena, ap kotiki ong irail masani: War ai metet, me pangalang komail! Komail en wia me wet, men kataman kin ia.',
        20: 'O pil dal en nim murin kasipong masani: Dal wet kadede kap ni mom en nt’ ai, me kapwilepilidi ong komail.',
        21: 'A kilang, pa en me pan pang ia la, me iang ia ni tepel o.',
        22: 'Nan melel, Nain aramas pan kokola duen a kileledier, a suedi ong aramas o, me a pan pangkila!',
        23: 'Irail ari pikikidi idok nan pung arail, is re irail, me pan wiada met?',
        24: 'Irail pil akamaiki nan pung arail, duen is me pan lapalap re irail.',
        25: 'A kotin masani ong irail: Nanmarki en wei pokon akan kin poe irail edi o me manaman akan kin adaneki monsap kalangan.',
        26: 'A komail sota pan dueta, a me lapalap re omail, i en dueta me tikitik, o me kin kaunda, en dueta me kin papa.',
        27: 'Pwe is me lapalap ren me mondi ni tepel de me kin papa? Kaidin i, me mondi ni tepel? A ngai dueta ladu pamail.',
        28: 'Nan komail me iang ia ni ai songesong.',
        29: 'Ngai ari kileledi ong komail wei eu, duen Sam ai kileledi ong ia er;',
        30: 'Pwe komail en manga o nim ni ai tepel nan ai wei o mondi pon men mondi ko, kakaun kainok en Israel eisokriau.',
        31: 'Kaun ap kotin masani: Simon, Simon, kilang, Satan ngongkin komail, pwen koko komail dueta wan prot.',
        32: 'A ngai me kapakapa kin uk, pwe om poson de nikila. A koe lao sapaledo kakelada ri om ol akan!',
        33: 'A a potoan ong i: Maing, i pan idauen ir lel nan imateng o matala.',
        34: 'A kotin masani: Petrus, I indai ong uk, nan malek sota pan kakorot ran wet, koe lao kamamki pan silepak, me koe asa ia.',
        35: 'A kotin masani ong irail: Ni ai kadar komail wei so ed en moni, o so ed en sailok, o so sut, meakot komail lekekilar? Re ap potoan ong: Sota.',
        36: 'I ari kotin masani ong irail: A met, me a ed en moni mia, en ale o pil ed en sailok, o me so a, i en netekila a likau, ap id netiada kodlas pot.',
        37: 'Pwe I indai ong komail, me intingidier, pil pan pwai ong ia: A wadawad ong me dipan akan, pwe me intingidier duen ngai, pan kaimwisokala.',
        38: 'Irail indada: Maing, kotin masani, iet kodlas riapot. A kotin masani ong irail. Ari, i eta.',
        39: 'I ari kotilang dol Oliwe, duen a kin wia; tounpadak kan idauenla i.',
        40: 'I lao lel ong wasa o, ap kotin masani ong irail: Komail kapakap pwe komail de ko ong nan songesong.',
        41: 'I ari tororela sang irail doo weita kapir won takai eu, ap kelepuki laolao.',
        42: 'Masani: Sam (ai), ma komui mauki, koti ki wei sang ia dal wet, ari so, kaidin insen ai, pwe kupur omui ta en wiaui.',
        43: 'Nan tounlang amen pwarado sang nanlang katinada i.',
        44: 'A ni a kotin pador ong mela, ap ngiangiang a laolao, lao pudo a likamata nta, me dingedingedi ong nan pwel.',
        45: 'A kotida sang a laolao o kotin pur ong tounpadak kan, ir mamair aki ar mamauk.',
        46: 'Masani ong irail: Da me komail mamairki? Paurida o kapakap, pwe komail de ko ong nan songesong!',
        47: 'A ni a kotin masani mepukat, kilang, pokon o, o me adaneki Iudas, amen ir ekriamen, tiong mo’rail, kaikai dong Iesus, pwen metik i.',
        48: 'A Iesus kotin masani ong i: Iudas, koe pan pang kila metik eu Nain aramas?',
        49: 'Irail me iang i lao kilanger me pan wiaui, rap indai ong i: Maing, se so pan wokieki ir kodlas?',
        50: 'Amen ir pala ladun samero lapalap amen o sara sang salong a pali maun.',
        51: 'Iesus ap kotin sapeng masani: Arier! I ap kotin sair salong a, kakelada i.',
        52: 'Iesus ap kotin masani ong samero lapalap akan, o kaun pan im en kaudok, o saumas akan, me ko dong i: Dueta lolap amen, me komail koko dong, wa kodlas o katiu kai?',
        53: 'Ni ran karos ngai iang komail nan im en kaudok, a komail sota man sair ia, pwe ansau wet omail ansau o manaman en rotorot.',
        54: 'Re ap saikidi i o kalualong ong nan im en samero lapalap o, a Petrus idauenla doowei sang.',
        55: 'Irail ap saunda kisiniai eu nan warong en kel o mod pena, a Petrus mondi nan pung arail.',
        56: 'A lidu men kilang i a momod impan kisiniai o kangkakil i indada:',
        57: 'Iet et pil iang i. I ari kamam kin i indada: Li, i sasa i.',
        58: 'A mur kis amen kilang i indada: Koe pil amen irail. A Petrus indada: O kaidin ngai!',
        59: 'Kadekadeo murin auer eu amen katitiki indada: Melel i men et iang i, pwe i kisan men Kaliläa.',
        60: 'A Petrus indada: O i poneponeki om kasokasoi! A pitipit ni a lokelokaia malek ap kakoroteda.',
        61: 'Kaun ap kotin saupeido masani Petrus. Petrus ap tamanda masan en Kaun, duen a kotin masani ong i: Mon malek kakorot, koe pan kamam kin ia pan silepak.',
        62: 'Petrus ari koieila sangesang kaualap.',
        63: 'A ol oko, me kolekol i, lalaue o woki i.',
        64: 'Irail lao perala silang i, ap idedok re a indada: Kopada, is i, me pikir uk ada?',
        65: 'O song en lalaue toto, me re ki ong i.',
        66: 'A lao ran pasang saumas akan o samero lapalap o saunkawewe kan ap pokon pena o kalua i dong nan arail kapung.',
        67: 'Indada: Ma koe Kristus, ap katiti ong kit! A kotin masani ong irail: Ma I pan indai ong komail, komail sota pan kamelele;',
        68: 'A ma I pan idok, komail sota pan sapeng, o pil sota lapwa ia da.',
        69: 'Ari, sang met Nain aramas pan mondi ni pali maun en roson en Kot.',
        70: 'Ir karos ap idok: Ari, sapwilim en Kot koe? A a kotin masani ong irail: Komail me indada, pwe ngai i.',
        71: 'Irail indada: Ari, menda apot kadede? Pwe pein kitail ronga sang nan au a.',
    },
    23: {
        1: 'TOUN pokon karos ap kasinenda kalualang i ren Pilatus.',
        2: 'Irail ari pikikidi impimpa i indada: Se diarada lap men et, me a kin kaweid sapung aramas akan o inapwiedi, ender nopwei ong nanmarki, ap inda, me dene pein i Kristus o nanmarki.',
        3: 'Pilatus ari idok re a masani: Nanmarki en Sus akan komui? A kotin sapeng i masani: Komui me inda.',
        4: 'Pilatus ap masani ong samero lapalap akan o pokon o: Sota dip, me i diar ren aramas men et.',
        5: 'A irail ngidingideki i indada: A kin kapeida aramas ni a kaukawewe sili nan Iudäa, tapiada Kaliläa kokodo lel sap wet.',
        6: 'Pilatus lao rongadar Kaliläa, ap idok, ma i aramas en Kaliläa men.',
        7: 'A i lao rongadar, me kisan toun wein Erodes, ap kadarala i ren Erodes, me pil kotikot Ierusalem ni ran oko.',
        8: 'Erodes lao masani Iesus, ap perenda kaualap, pwe me warai a kin anane udial i, pweki me toto a rongadar iran i, o a pil kaporoporeki, me a pan udial kilel eu sang re a.',
        9: 'I ari kalelapok re a ni masan toto. A i sota kotin man sapeng i.',
        10: 'A samero lapalap o saunkawewe kan kasinenda o impimpa i kaualap.',
        11: 'A Erodes o na saunpei kan mamaleki i o likauki i likau puetepuet o kapure wong i ren Pilatus.',
        12: 'A ni ran ota Pilatus o Erodes insenemau pena, pwe mas o ira imwintiti pena.',
        13: 'A Pilatus kapokon pena samero lapalap, o monsap, o aramas akan,',
        14: 'Ap masani ong irail: Komail wa dong ia aramas men et, dene kaweid sapung aramas akan. A kilang, i kalekalelapok re a mo’mail, ap sota dip, me i diar ren aramas men et, duen me komail katikatipiaki i.',
        15: 'Erodes pil so, pwe i kadar wong i komail. A kilang, sota me a wiadar pwen kame kila i.',
        16: 'Ari, i pan woki i ap lapwada.',
        17: 'Pwe a pan udan lapwa dang irail meamen nin kamadip o.',
        18: 'Irail karos ap likelikwir indada: Kasapokela men et o lapwa dong kit Parapas!',
        19: 'Me lokidokilar nan imateng aki moromorong eu o kamela en aramas amen, me wiauier nan kanim o.',
        20: 'Pilatus ari men lapwada Iesus, ap pil masani ong irail.',
        21: 'A irail likelikwir indada: Kalopuela, kalopuela i!',
        22: 'A masani ong irail kasilepak: Pwe me sued da, me a wiadar? Sota me i diaradar re a, me i en kamata kila. Ari, i pan woki i ap lapwada.',
        23: 'A irail nantiong weriwereda ngidingidiki i, me a en lopuela; o ar weriwer o en samero lapalap akan lalaudelar.',
        24: 'Pilatus ap inda, me ar poekipoek en pwaida,',
        25: 'Ap lapwada i, me lokidokilar nan imateng aki moromorong eu o kamela en aramas amen, me irail poeki, ap mueid ong irail Iesus, en wiai ong i duen insen arail.',
        26: 'O ni arail kalua wei i, re ap saikidi Simon men Kirene, me kodo sang nan sap o. Ir ari kidang po a lopu, pwen wala murin Iesus.',
        27: 'O pokon kalaimun idauenla i, o li kai me sangesang o mamaukeki i.',
        28: 'Iesus kotin saupei dong irail masani: Li en Ierusalem akan, ender sangesang kin ia, a sangesang kin pein komail o noumail seri kan.',
        29: 'Pwe kilang, ni ran oko kokodo aramas pan indinda: Meid pai li dapwan o irail me sota naitik, o didi kan, me sota kadidi!',
        30: 'Re ap pan pikikidi ekeker ong nana kan: Pupedi ong po at! O ong dol akan: Kadupal kit edi!',
        31: 'Pwe ma re wiadar mepukat ong tuka maur, da me re pan wia ong tuka mongedi?',
        32: 'A pil lolap riamen iang i kalua wei kamela.',
        33: 'Irail lao lei wasa, me adaneki pondal en mong, ap kalopuela i o me lolap oko, amen ni pali maun o amen ni pali maing.',
        34: 'Iesus ap kotin masani: Sam (ai), Kom kotin maki ong irail, pwe irail sasa, me re wiawia. Irail ari nene pasang sapwilim a likau kan o kadoropwa kida.',
        35: 'Aramas me u kangkakil o monsap akan iang irail kapikapiti i indada: A kamaureda akai, i en kamaureda pein i, ma i Kristus sapwilim en Kot.',
        36: 'A saunpei kan pil kapikapiti i, kai ong i, ki ong i pinika,',
        37: 'Indada: Ma koe Nanmarki en Sus akan, en kapitila pein uk.',
        38: 'A pil inting eu, me intingidier ponangen i ni lokaia en Krik, o Latain, o Ipru: Iet Nanmarki en Sus akan.',
        39: 'A amen ren lolap oko, me langadar, lalaue i indada: Kaidin koe Kristus Kapiti sang pein uk o kit!',
        40: 'Me teio ap sapeng, kapung ong i indada: Koe pil sota masak Kot ni om iang kadeik wet?',
        41: 'Pwe ata kalokolok me pung, pwe iduen ata wiawia kan, a ol men et sota wiadar meakot me sued.',
        42: 'Ap potoan ong Iesus: Maing, re kotin kupura ia, lao re kotida nan wei ar.',
        43: 'Iesus ap kotin masani ong i: Melel I indai ong uk, ran wet koe pan iang ia mi nan paradis.',
        44: 'Ni auer kawonu ap rotorotala nan sap karos lao lel auer kaduau,',
        45: 'O katipin rotorotala, o likau en pera en im en kaudok o dei pasang sang poa lel pa.',
        46: 'Iesus ap kotin kapitie laudeda masani: Sam (ai), i mueidalang ngen i nan lim omui kan. A lao kotin masanier met, ap kotin poular.',
        47: 'A saumas en saunpei o, ni a kilanger me wiauier, ap kapikapinga Kot indada: Melel, aramas men et me pung.',
        48: 'O aramas karos me pokon penaer pwen iang kilang, lao kilanger me wiauier, ap pikir maramar arail o pure pasang.',
        49: 'A kompokepa kan karos o li akan, me idauendo i sang Kaliläa, u kailawei, kilekilang mepukat.',
        50: 'O kilang ol amen, me mar a Iosep, saunkapung amen, ol mau o pung amen,',
        51: 'Me sota apali ong irail ni ar kapukapung o wiawia kan, men Arimatia, kanim eu en Iudäa, me pil auiaui wein Kot,',
        52: 'I me poto dong Pilatus poekipoeki kalep en Iesus.',
        53: 'I ari kidi sang i o kidimki pena likau linen kaselel o kidi ong nan sousou, me weiweida nan paip, wasa me saikenta amen saredi ia.',
        54: 'A ran o ran en kaonop o sapat korendor.',
        55: 'A li akan, me iang i kodido sang Kaliläa, pil iang udial sousou o, wasa me kalep a nekinekid ia.',
        56: 'Irail ap purer o kaonopada potik kai o men usor, re ap kamol ni ran en sapat duen kusoned o.',
    },
    24: {
        1: 'A NIN tapin wik, nin soran kaualap re pwara dong sousou o, wado potik kai me re kaonopadar;',
        2: 'Irail ari diaradar, me takai o kadapura sang sousou o,',
        3: 'O irail lao pedelong ong lole, ap sota diarada kalep en Kaun Iesus.',
        4: 'Kadekadeo irail lao insensued kidar, kilang, ol riamen, me likau kida likau linang, ap pwara dong irail.',
        5: 'Irail lao masapwekadar o ikiokidi nan pwel, ira ap masani ong irail: Da me komail raparapaki me maur amen ren me melar akan?',
        6: 'A soer kotikot met, a iasadar. Tamanda, me a kotin masani ong komail ni a kotikoteta Kaliläa,',
        7: 'Mamasani: Nain aramas pan pangalang ni pa en me dipan akan, o lopuela, o ni ran kasilu a pan iasada.',
        8: 'Ir ari tamanda a masan akan.',
        9: 'O purodo sang nin sousou o, ap kaireki mepukat ong ekamen ko o ong me tei kan karos.',
        10: 'Maria men Makdala, o Ioana, o Maria in en Iokopus, o me tei ko me iang irail, me kaireki mepukat ong wanporon akan.',
        11: 'A arail kasoi likamata kasoi likam pot re’rail, ap sota kamelele.',
        12: 'Petrus ap uda tangalang sousou o, rukedi ong lole, ap diarada, me likau linen akan ta wonon wasa kis, ap purodo sang o puriamui kida me wiauier.',
        13: 'A kilang ni ran ota riamen re’rail momaitelang kisin kanim eu ad a Emaus; a doo sang Ierusalem mail wonu de isu.',
        14: 'Ira ari kasokasoi penaer duen mepukat karos.',
        15: 'Kadekadeo ni ara kasokasoi o idedok pena, pein Iesus ap kotin pwara dong ira o iang ira kotila.',
        16: 'A mas ara me atiat, pwe re de asa i.',
        17: 'I ari kotin masani ong ira: Da me koma kasokasoi pena ni oma alialu, o da me koma insensued kila?',
        18: 'Amen ira, me ad a Kleopas, ap sapeng indang i: Koe men wai ta men nan Ierusalem, me sasa, me wiauier wasa o ni ran pukat?',
        19: 'A kotin masani ong ira: Pwe dakot? Ira ap indang i: Duen Iesus en Nasaret, me saukop manaman amen ni a wiawia o masan akan mon Kot o aramas karos.',
        20: 'O duen samero lapalap o atail saumas akan ar pangala i pwen pakadeikada ong matala o kalopuela i.',
        21: 'A se kiki ong, me a pan kotin kamaioda wein Israel. Ari ran wet pong sili pong murin mepukat wiauier.',
        22: 'O pil kis at li akai kamasak kin kit ar pwaralang sousou o sangkonai.',
        23: 'Ni ar sota diar kalep a, rap puredo indada, me re diaradar sansal en tounlang kai, me katitiki, me a iasadar,',
        24: 'O kis at kai kolang sousou o, ap diaradar, duen li oko kasokasoida, a i me re sota diarada.',
        25: 'A kotin masani ong ira: O koma meid lolepon o pwand nan mongiong omail, en kamelele meakan, me saukop akan kopadar.',
        26: 'Kaidin i, me udan Kristus en kalokolok ap kodalang a lingan?',
        27: 'A ap kotin kawewe ong ira kisin likau kan duen pein i, tapiada ni Moses kokodo lel saukop akan.',
        28: 'Irail ap koren iong kanim, me irail koko ong. I ari kasongesong ira, dene a pan kotin daulul.',
        29: 'Ira ap ngidingidiki i potoan ong: Kom kotikoteta re at, pwe a pan wasa pongier o ran wet koren iong imwisokela. A ap kotilong ong nan im o, pwen mimieta re ra.',
        30: 'Kadekadeo ni a kotin iang ira ni tepel o, a kotin limada prot, laolaoki, a lao pilitiki pena, a kotiki ong ira.',
        31: 'Mas ara ap pad pasanger, ira ap asa i. A ap kotin soredi sang mo’ra.',
        32: 'Ira ap inda nan pung ara: Mongiong ata sota mokimokid ni a kotin mamasani ong kita pon al o, ni a kotin kawewe ong kita kisin likau kan?',
        33: 'Ira ari uda ni auer ota o purelang Ierusalem, o diarada ekamen ko, o me iang ir, kot pena wasa takis,',
        34: 'Katitiki: Nan melel Kaun o kotin iasadar o pwara dong Simon,',
        35: 'Ira ap kasokasoi, me wiauier nani al o, o duen ara asaki i a pilitiki pasang prot.',
        36: 'A ni ar masan pena mepukat, pein Iesus ap kotin pwara dong nan pung arail masani ong ir: Komail popol!',
        37: 'Irail ari masapwekadar o wapondar, o re kiki ong, me ani men, me re udial.',
        38: 'A kotin masani ong irail: Da me komail masak ki? O menda lamelam pukat mi nan mongiong omail?',
        39: 'Komail kilang pa i kat o na i kat, pwe pein ngai ta. Doke ia o kilang, pwe ani sota kin uduk o ti, duen omail kilang ia.',
        40: 'A lao masani mepukat, ap kasale ong irail lim a o aluwilu a kan.',
        41: 'A ni ar sota non kamelele pweki ar peren o puriamuiki, ap kotin masani ong irail: Sota kan omail met?',
        42: 'Rap ki ong i kisan mam inin o onik.',
        43: 'I ari konot mo’rail.',
        44: 'A kotin masani ong irail: I masan akan, me I ki ong komail er, ni ai mimieta re omail, pwe karos en pwaida, me intingidier duen ngai nan kapung en Moses, o saukop akan, o psalm akan.',
        45: 'I ap kotin kalolikongi irail, pwe ren dedeki kisin likau kai.',
        46: 'O kotin masani ong irail iduen a intingidier, o iduen udan kalokolok en Kristus, ap maureda sang ren me melar akan ni ran kasilu,',
        47: 'O padapadaki ong wei karos ni mar a, ren kalula, pwe dip akan en lapwada, a pan tapida nan Ierusalem.',
        48: 'A komail me saunkadede en mepukat.',
        49: 'A kilang, I pan kadara dong komail, me Sam ai inaukidar. A komail pan mimieta nan kanim o, komail lao audaudekier manaman sang poa.',
        50: 'A kotin kalua ir alang Petanien, kotikida lim a, kapai irail ada.',
        51: 'Kadekadeo ni a kotin kapal ir ada, a kotiwei sang irail, kotidala nanlang.',
        52: 'Irail ari kaudok ong i, ap pure dong Ierusalem perenda kaualap;',
        53: 'O re potopot nan im en kaudok kapinga o kaudok ong Kot.',
    },
}
